window.MANOBRAS = {"grupos": [{"id": "cabeca", "titulo": "Cabeça, pescoço e pele"}, {"id": "torax", "titulo": "Tórax e mamas"}, {"id": "mmss", "titulo": "Membro superior"}, {"id": "coluna", "titulo": "Coluna e tronco"}, {"id": "mmii", "titulo": "Membro inferior"}, {"id": "neuro", "titulo": "Exame neurológico"}, {"id": "gufem", "titulo": "Genitourinário feminino"}, {"id": "gumasc", "titulo": "Genitourinário masculino"}], "manobras": [{"nome": "Spurling", "epo": "Spurling", "como": "Paciente sentado, musculatura cervical relaxada. Examinador atrás: inclina a cabeça para o lado sintomático, estende o pescoço e aplica compressão axial suave no topo da cabeça.", "alterado": "Reprodução de dor ou parestesia irradiada para o membro superior do mesmo lado.", "significado": "Compressão de raiz cervical. Dor cervical local isolada é inespecífica. Não fazer com suspeita de fratura ou instabilidade.", "slide": 6, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "cabeca"}, {"nome": "Avaliação de via aérea, respiração e circulação (ABC)", "epo": "", "como": "Inspeção de via aérea (voz, estridor), ausculta (sibilância), pulso e PA, e consciência. Faça em paralelo, em equipe.", "alterado": "Estridor, voz alterada, sibilância, hipotensão ou síncope.", "significado": "Sinais que não se pode perder na anafilaxia: adrenalina IM sem atraso.", "slide": 9, "pdf": "pdf/aula-06.pdf", "aula": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "aulaId": "aula-06", "grupo": "cabeca"}, {"nome": "Palpação de temperatura e umidade", "epo": "", "como": "Dorso dos dedos, comparando lados e segmentos homólogos.", "alterado": "Assimetria de temperatura ou umidade.", "significado": "Alteração de perfusão ou de processo local; registre a região.", "slide": 10, "pdf": "pdf/aula-06-1.pdf", "aula": "Aula 6.1 - Semiologia tegumentar", "aulaId": "aula-06-1", "grupo": "cabeca"}, {"nome": "Prega cutânea (turgor)", "epo": "", "como": "Pince a pele do dorso da mão ou do abdome, solte e observe o retorno.", "alterado": "A prega persiste por mais tempo que o normal.", "significado": "Turgor diminuído, a interpretar no contexto: desidratação, idade e perda de peso.", "slide": 14, "pdf": "pdf/aula-06-1.pdf", "aula": "Aula 6.1 - Semiologia tegumentar", "aulaId": "aula-06-1", "grupo": "cabeca"}, {"nome": "Pesquisa de dor cutânea desproporcional", "epo": "", "como": "Compare a dor relatada com o aspecto da lesão visível, perguntando e observando a pele.", "alterado": "Dor intensa desproporcional ao que se vê.", "significado": "Pista de SSJ/NET; pede avaliação dirigida, sem tranquilizar pelo tamanho.", "slide": 19, "pdf": "pdf/aula-06.pdf", "aula": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "aulaId": "aula-06", "grupo": "cabeca"}, {"nome": "Exame ativo de mucosas", "epo": "", "como": "Examinar boca, lábios, conjuntivas, genitais, com o paciente consciente e consentindo.", "alterado": "Erosões dolorosas, fotofobia, ardor ocular, dificuldade para ingerir.", "significado": "Suspeita de SSJ/NET: avaliação oftalmológica precoce e internação.", "slide": 20, "pdf": "pdf/aula-06.pdf", "aula": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "aulaId": "aula-06", "grupo": "cabeca"}, {"nome": "Classificação pelo descolamento", "epo": "", "como": "Estime a superfície corporal com epiderme descolada ou destacável (não o eritema).", "alterado": "Descolamento de 10 a 30% (sobreposição) ou mais de 30% (NET).", "significado": "SSJ abaixo de 10%. A classificação orienta a gravidade e a admissão.", "slide": 21, "pdf": "pdf/aula-06.pdf", "aula": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "aulaId": "aula-06", "grupo": "cabeca"}, {"nome": "Palpação de elevação", "epo": "", "como": "Passe a polpa do dedo sobre a lesão e compare com a pele vizinha.", "alterado": "Relevo palpável, com ou sem consistência sólida.", "significado": "Mácula (plana) versus pápula, placa ou nódulo (elevados). Só o tato confirma elevação.", "slide": 25, "pdf": "pdf/aula-06-1.pdf", "aula": "Aula 6.1 - Semiologia tegumentar", "aulaId": "aula-06-1", "grupo": "cabeca"}, {"nome": "SCORTEN", "epo": "", "como": "Some um ponto para cada critério: idade 40 anos ou mais; neoplasia; FC 120 bpm ou mais; descolamento 10% ou mais; ureia acima de 10 mmol/L; glicose acima de 14 mmol/L; bicarbonato abaixo de 20 mmol/L. Calcule em 24 horas e no dia 3.", "alterado": "Escore alto (quanto mais critérios, maior a mortalidade estimada).", "significado": "Prognóstico e apoio para a admissão em terapia intensiva ou centro de queimados.", "slide": 25, "pdf": "pdf/aula-06.pdf", "aula": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "aulaId": "aula-06", "grupo": "cabeca"}, {"nome": "Vitropressão", "epo": "", "como": "Aplique uma lâmina de vidro sobre a lesão avermelhada e observe a cor sob pressão.", "alterado": "A cor persiste sob a lâmina (não empalidece).", "significado": "Púrpura, por extravasamento sanguíneo. Se empalidece, é eritema, por vasodilatação.", "slide": 26, "pdf": "pdf/aula-06-1.pdf", "aula": "Aula 6.1 - Semiologia tegumentar", "aulaId": "aula-06-1", "grupo": "cabeca"}, {"nome": "Teste de atrito (dermografismo)", "epo": "", "como": "Risque a pele com um objeto romo, de forma leve, e observe a região após alguns minutos.", "alterado": "Urticas lineares no trajeto do atrito.", "significado": "Dermografismo: urticas após atrito. Forma de urticária; observe a duração das lesões.", "slide": 31, "pdf": "pdf/aula-06-1.pdf", "aula": "Aula 6.1 - Semiologia tegumentar", "aulaId": "aula-06-1", "grupo": "cabeca"}, {"nome": "Expansibilidade torácica", "epo": "", "como": "Avaliar a expansibilidade do tórax durante a respiração (o slide 8 não detalha a técnica).", "alterado": "Expansibilidade reduzida.", "significado": "Expansibilidade torácica reduzida faz parte do quadro da espondilite anquilosante (slide 8).", "slide": 8, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "torax"}, {"nome": "Classificação de Tanner", "epo": "Tanner", "como": "Inspeção do desenvolvimento mamário, M1 a M5.", "alterado": "Desenvolvimento fora da faixa esperada.", "significado": "Avalia o desenvolvimento puberal.", "slide": 11, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Inspeção estática", "epo": "", "como": "Paciente sentada, braços ao lado do tronco; observar simetria, pele, contorno, circulação e complexo areolopapilar.", "alterado": "Assimetria, retração, edema, casca de laranja, retração do mamilo.", "significado": "Sinais visíveis de alerta exigem referência urgente.", "slide": 19, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Inspeção dinâmica com braços elevados", "epo": "Cooper", "como": "Paciente eleva os braços acima da cabeça; observar o sulco inframamário.", "alterado": "Retração, depressão ou assimetria que não aparecem em repouso.", "significado": "Estira os ligamentos de Cooper e revela fixações.", "slide": 20, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Contração do peitoral", "epo": "", "como": "Mãos na cintura, comprimindo os quadris; contrai o músculo peitoral.", "alterado": "Retração que se acentua; nódulo que se fixa à fáscia.", "significado": "Testa a fixação do nódulo à fáscia peitoral.", "slide": 21, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Mama pendente", "epo": "", "como": "Inclinação do tronco para frente, com as mamas pendentes.", "alterado": "Fixações profundas, assimetria de contorno ou desvio do mamilo.", "significado": "Essencial em mamas volumosas ou pendulares.", "slide": 21, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Palpação das axilas (deslizante)", "epo": "", "como": "Paciente sentada, braço relaxado apoiado; mão contralateral com dedos até o ápice da axila; tracionar as polpas contra o gradil costal.", "alterado": "Linfonodo de 1 cm ou mais, duro, fixo ou coalescente.", "significado": "Linfadenopatia axilar suspeita: encaminhamento urgente.", "slide": 25, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Palpação das fossas supra e infraclaviculares", "epo": "", "como": "Palpar as fossas supra e infraclaviculares, junto com a axila (o slide não detalha a técnica).", "alterado": "Linfonodo supraclavicular ou infraclavicular duro ou fixo.", "significado": "Metástase suspeita.", "slide": 26, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Palpação com a técnica de Velpeau ou Bloodgood", "epo": "Velpeau", "como": "Velpeau: face palmar dos dedos; Bloodgood: falanges distais.", "alterado": "Nódulo ou área de espessamento.", "significado": "Técnicas clássicas de palpação.", "slide": 28, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Palpação mamária em faixas verticais", "epo": "", "como": "Decúbito dorsal; polpas digitais; três pressões no mesmo ponto; faixas de um dedo de largura com sobreposição.", "alterado": "Nódulo endurecido, irregular, de limites imprecisos.", "significado": "Padrão ouro para massas dominantes.", "slide": 29, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Expressão papilar", "epo": "", "como": "Testar a elasticidade da papila; compressão radial guiada da aréola.", "alterado": "Papila espessa e inelástica; secreção de ducto único.", "significado": "Papila inelástica: forte suspeita de malignidade subjacente.", "slide": 30, "pdf": "pdf/aula-09-2.pdf", "aula": "Aula 9.2 - Semiologia das mamas", "aulaId": "aula-09-2", "grupo": "torax"}, {"nome": "Contagem e distribuição articular", "epo": "", "como": "Conte as articulações inflamadas e mapeie a distribuição: simetria, eixo axial e articulações periféricas.", "alterado": "1 articulação (monoartrite), 2 a 4 (oligoartrite), 5 ou mais (poliartrite).", "significado": "Define o padrão sindrômico e a prioridade diferencial.", "slide": 5, "pdf": "pdf/aula-07.pdf", "aula": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "aulaId": "aula-07", "grupo": "mmss"}, {"nome": "Investigação de manifestações extra-articulares", "epo": "", "como": "Interroge e examine olhos, pele, unhas, intestino e vias urinárias durante o exame articular.", "alterado": "Olho vermelho doloroso, psoríase, diarreia crônica, uretrite ou fenômeno de Raynaud.", "significado": "Sugere espondiloartrite, artrite psoriásica, doença inflamatória intestinal ou colagenose.", "slide": 8, "pdf": "pdf/aula-07.pdf", "aula": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "aulaId": "aula-07", "grupo": "mmss"}, {"nome": "Artrocentese diagnóstica", "epo": "", "como": "Coleta de líquido sinovial para celularidade, Gram, cultura e pesquisa de cristais.", "alterado": "Contagem celular alta, cultura positiva ou cristais específicos.", "significado": "Confirma infecção ou cristais. Nenhum achado clínico isolado substitui a artrocentese em monoartrite aguda inflamatória.", "slide": 10, "pdf": "pdf/aula-07.pdf", "aula": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "aulaId": "aula-07", "grupo": "mmss"}, {"nome": "Exame básico do ombro (inspeção, palpação e mobilidade)", "epo": "", "como": "Inspecione contornos e ritmo escapulotorácico; palpe AC, tubérculos e coracoide; compare arcos de elevação e rotações.", "alterado": "Assimetria, dor palpatória focal, limitação de arco.", "significado": "Mapeia a função antes dos testes especiais.", "slide": 18, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Arco doloroso", "epo": "", "como": "Abdução ativa lenta, tronco ereto; registrar o início e o término da dor.", "alterado": "Dor no arco intermediário ou no arco final extremo.", "significado": "Pinçamento subacromial (intermediário) ou articulação AC (final).", "slide": 19, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Neer", "epo": "Neer", "como": "Estabilize a escápula; cotovelo estendido; elevação passiva em flexão com leve rotação interna.", "alterado": "Dor habitual reproduzida.", "significado": "Pinçamento da grande tuberosidade contra o arco coracoacromial.", "slide": 20, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Hawkins", "epo": "Hawkins", "como": "Ombro a 90 graus, cotovelo fletido a 90; rotação interna passiva.", "alterado": "Dor subacromial habitual reproduzida.", "significado": "Compõe o somatório com Neer e o arco doloroso.", "slide": 21, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Jobe", "epo": "Jobe", "como": "Braços a 90 graus no plano escapular, polegares para baixo; resistência para baixo.", "alterado": "Dor ou incapacidade de sustentação.", "significado": "Supraespinhoso. Distinga dor de fraqueza.", "slide": 24, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Patte", "epo": "Patte", "como": "Ombro a 90 graus, cotovelo a 90; rotação externa resistida no antebraço.", "alterado": "Perda de força na rotação externa.", "significado": "Infraespinhoso. Observe a compensação do tronco.", "slide": 25, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Gerber", "epo": "Gerber", "como": "Dorso da mão na lombar; afastar a mão das costas contra gravidade ou resistência.", "alterado": "Incapacidade de afastar a mão.", "significado": "Subescapular, se não houver rigidez capsular.", "slide": 26, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Speed", "epo": "Speed", "como": "Cotovelo estendido, antebraço supinado; elevação anterior contra resistência.", "alterado": "Dor focal no sulco bicipital.", "significado": "Tendinopatia da porção longa do bíceps.", "slide": 27, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Palpação do aumento de volume", "epo": "", "como": "Palpe a consistência e a relação com a interlinha, e procure calor e flutuação.", "alterado": "Consistência elástica ou esponjosa com dor às interlinhas (sinovite); consistência dura e nodular (osteófito).", "significado": "Diferencia sinovite de proliferação óssea e de edema subcutâneo.", "slide": 27, "pdf": "pdf/aula-07.pdf", "aula": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "aulaId": "aula-07", "grupo": "mmss"}, {"nome": "Adução cruzada (AC)", "epo": "", "como": "Braço a 90 graus à frente; adução horizontal controlada.", "alterado": "Dor pontual na articulação AC.", "significado": "Patologia AC. Dor posterior por alongamento não é compressão.", "slide": 28, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Matriz de diferenciação cinética", "epo": "", "como": "Compare movimento ativo, passivo e resistido, e a palpação, entre a articulação e a estrutura periarticular.", "alterado": "Passivo limitado com resistido indolor sugere articular (cápsula); passivo preservado com resistido doloroso sugere tendão ou bursa.", "significado": "Separa doença articular verdadeira de periarticular, e orienta a investigação.", "slide": 30, "pdf": "pdf/aula-07.pdf", "aula": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "aulaId": "aula-07", "grupo": "mmss"}, {"nome": "Cozen", "epo": "Cozen", "como": "Extensão do punho contra resistência; palpe o epicôndilo lateral.", "alterado": "Dor focada na origem extensora lateral.", "significado": "Epicondilite lateral.", "slide": 31, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Flexão resistida do punho (epicôndilo medial)", "epo": "", "como": "Antebraço supinado; flexão do punho contra resistência.", "alterado": "Dor focal na origem flexora medial; parestesia no 4º e 5º dedos.", "significado": "Epicondilite medial; parestesia exige avaliação do nervo ulnar.", "slide": 32, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Phalen", "epo": "Phalen", "como": "Flexão dos punhos por até 60 segundos.", "alterado": "Parestesia no território mediano.", "significado": "Compressão do mediano. Negativo não exclui neuropatia.", "slide": 37, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Tinel", "epo": "Tinel", "como": "Percutir de leve, repetidamente, o nervo mediano no punho, na borda radial do tendão palmar longo.", "alterado": "Parestesia (formigamento) no território mediano.", "significado": "Sugere compressão do mediano. Dor local à percussão não é Tinel positivo; nenhum dos dois testes (Tinel e Phalen), isolado, confirma ou exclui.", "slide": 38, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Finkelstein (De Quervain)", "epo": "Finkelstein", "como": "Desvio ulnar do punho com polegar sob os dedos; condução suave.", "alterado": "Dor sobre o estiloide radial.", "significado": "Tenossinovite do primeiro compartimento dorsal.", "slide": 39, "pdf": "pdf/aula-07-1.pdf", "aula": "Aula 7.1 - Semiologia osteomioarticular I", "aulaId": "aula-07-1", "grupo": "mmss"}, {"nome": "Teste de Adams (flexão anterior do tronco)", "epo": "Adams", "como": "Paciente de pé, joelhos estendidos, braços pendentes, flexão do tronco. Examinador observa por trás, tangencialmente ao dorso.", "alterado": "Giba costal ou lombar que persiste na flexão.", "significado": "Escoliose estrutural. Se a giba se corrige na flexão, é escoliose postural.", "slide": 4, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "coluna"}, {"nome": "Schober", "epo": "Schober", "como": "Marque A na linha média, no nível das covinhas de Vênus, e B 10 cm acima. Peça flexão anterior máxima sem fletir os joelhos e meça A-B.", "alterado": "Aumento menor que 5 cm (A-B menor que 20 cm).", "significado": "Limitação da flexão lombar, como na espondilite anquilosante. Não confirma espondilite isoladamente.", "slide": 5, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "coluna"}, {"nome": "Lasègue (elevação do membro estendido)", "epo": "Lasègue", "como": "Decúbito dorsal, membro estendido e relaxado. Segure o tornozelo, mantenha o joelho estendido e eleve lentamente. Registre o ângulo de início da dor.", "alterado": "Dor irradiada abaixo do joelho entre cerca de 30 e 70 graus.", "significado": "Tensão de raízes L4 a S1, sobretudo L5 e S1. Dor só na face posterior da coxa indica isquiotibiais, e não é positivo.", "slide": 7, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "coluna"}, {"nome": "Lasègue cruzado", "epo": "Lasègue", "como": "Eleve o membro sadio, com o paciente em decúbito dorsal.", "alterado": "Reprodução da ciatalgia do lado afetado.", "significado": "Compressão radicular. Pouco sensível, muito específico.", "slide": 7, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "coluna"}, {"nome": "Schober", "epo": "Schober", "como": "Paciente em pé, marcar a referência lombossacra e 10 cm acima; pedir flexão máxima do tronco e medir a distância final.", "alterado": "Aumento menor que 5 cm.", "significado": "Limitação da flexão lombar, compatível com espondilite anquilosante.", "slide": 8, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "coluna"}, {"nome": "Bragard", "epo": "Bragard", "como": "Após Lasègue positivo, abaixe o membro 5 a 10 graus, mantenha-o elevado e faça dorsiflexão passiva do pé.", "alterado": "Retorno da dor irradiada.", "significado": "Tensão neural radicular, e não dor muscular.", "slide": 8, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "coluna"}, {"nome": "Lasègue", "epo": "Lasègue", "como": "Decúbito dorsal; elevar o membro estendido, sustentando o calcanhar; registrar o ângulo de início da dor no trajeto.", "alterado": "Dor irradiada além do joelho entre 30 e 45 graus e 70 graus.", "significado": "Tensão radicular (L5 e S1 mais comuns). Negativo torna hérnia improvável.", "slide": 16, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "coluna"}, {"nome": "Lasègue cruzado", "epo": "Lasègue", "como": "Elevação do membro contralateral com o paciente em decúbito dorsal.", "alterado": "Dor no membro examinado.", "significado": "Muito específico, pouco sensível para hérnia lombar.", "slide": 16, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "coluna"}, {"nome": "Ponto-gatilho", "epo": "", "como": "Palpação de faixa tensa no músculo e pressão direta sobre o ponto.", "alterado": "Pressão reproduz a dor habitual.", "significado": "Síndrome dolorosa miofascial, distinta da fibromialgia.", "slide": 22, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "coluna"}, {"nome": "Patrick (FABER)", "epo": "Patrick", "como": "Decúbito dorsal. Membro em posição de 4, maléolo lateral sobre a coxa contralateral. Uma mão estabiliza a espinha ilíaca; a outra pressiona o joelho em direção à maca.", "alterado": "Dor inguinal ou dor posterior sacroilíaca reproduzida.", "significado": "Dor inguinal: coxofemoral. Dor posterior: sacroilíaca. É teste de provocação e não define diagnóstico sozinho.", "slide": 12, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Gaenslen", "epo": "Gaenslen", "como": "Paciente em decúbito dorsal, com a nádega do lado testado na borda da maca. Flexione o quadril contralateral ao máximo e deixe o membro testado pendente, pressionando em hiperextensão.", "alterado": "Reprodução da dor posterior habitual na região sacroilíaca.", "significado": "Dor sacroilíaca. Não comprova sacroiliíte isoladamente.", "slide": 13, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Rotação do quadril em 90 graus", "epo": "", "como": "Decúbito dorsal, quadril e joelho a 90 graus. Uma mão estabiliza o joelho; a outra conduz o tornozelo. Pé levado para fora (afasta-se da linha média) = rotação interna; pé levado para dentro = rotação externa. A rotação nomeia o movimento da cabeça do fêmur, e não do pé.", "alterado": "Limitação de amplitude, sobretudo da rotação interna, comparada ao lado oposto.", "significado": "Artrose coxofemoral (rotação interna é a primeira a limitar). Dor inguinal sugere origem intra-articular; dor lateral com trocânter, periarticular.", "slide": 14, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Marcha nos calcanhares e na ponta dos pés", "epo": "", "como": "Pedir ao paciente caminhar apenas sobre os calcanhares e depois apenas sobre a ponta dos pés.", "alterado": "Incapacidade sobre os calcanhares (L4-L5) ou sobre a ponta dos pés (S1).", "significado": "Teste rápido de raiz à beira do leito.", "slide": 15, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "mmii"}, {"nome": "Trendelenburg", "epo": "Trendelenburg", "como": "Paciente em pé, examinador atrás observando as cristas ilíacas. Apoio unipodal por cerca de 30 segundos, depois o outro lado.", "alterado": "Queda da pelve do lado do pé elevado.", "significado": "Fraqueza dos abdutores do quadril (glúteo médio) do lado apoiado. Na marcha gera a marcha de Trendelenburg.", "slide": 15, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Thomas", "epo": "Thomas", "como": "Decúbito dorsal. O paciente abraça o joelho oposto e o leva ao tórax até retificar a lordose lombar; observe a coxa testada.", "alterado": "A coxa testada se eleva da maca.", "significado": "Contratura em flexão do quadril. Com a perna pendente na borda da maca, a extensão do joelho sugere encurtamento do reto femoral. Sem retificar a lordose, a hiperlordose esconde a contratura (falso-negativo).", "slide": 16, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Sinal da onda", "epo": "", "como": "Joelho estendido, quadríceps relaxado. Ordenhe o recesso suprapatelar; pressione a face medial; percuta ou deslize a face lateral.", "alterado": "Onda de líquido que reaparece na face medial.", "significado": "Derrame pequeno. Nos derrames volumosos e tensos pode não aparecer.", "slide": 18, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Choque patelar (sinal da tecla)", "epo": "", "como": "Decúbito dorsal, joelho estendido e quadríceps relaxado. Comprima o recesso suprapatelar e empurre a patela contra o fêmur com movimento rápido.", "alterado": "A patela desce, choca contra o fêmur e retorna.", "significado": "Derrame moderado a volumoso. Falso-negativo com derrame pequeno ou muito tenso.", "slide": 19, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Lachman", "epo": "Lachman", "como": "Joelho a 15 a 30 graus, isquiotibiais relaxados. Estabilize o fêmur distal e trace a tíbia proximal para frente.", "alterado": "Translação anterior maior que a do lado oposto, com parada mole.", "significado": "Lesão do LCA. Teste de escolha. Defesa dos isquiotibiais gera falso-negativo.", "slide": 20, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Gaveta anterior", "epo": "", "como": "Quadril a 45 graus, joelho a 90 graus, pé estabilizado. Trace a tíbia para frente. Antes, observe o sinal da queda posterior.", "alterado": "Deslizamento anterior excessivo sem ponto final firme.", "significado": "Lesão do LCA. Se a tíbia já estava caída para trás, o achado é falso-positivo e sugere LCP.", "slide": 23, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Gaveta posterior (sinal da queda posterior)", "epo": "", "como": "Mesma posição da gaveta anterior. Observe a tíbia de perfil e empurre a tíbia proximal para trás.", "alterado": "Tíbia caída para trás ou deslocamento posterior excessivo sem ponto final.", "significado": "Lesão do LCP.", "slide": 24, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Estresse em valgo", "epo": "", "como": "Decúbito dorsal, coxa levemente abduzida. Uma mão empurra o joelho para medial e a outra puxa o tornozelo para lateral. Teste em extensão e em 20 a 30 graus.", "alterado": "Abertura medial excessiva sem ponto final firme, ou dor na interlinha medial.", "significado": "Lesão do LCM. Abertura em extensão sugere lesão associada.", "slide": 25, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Estresse em varo", "epo": "", "como": "Mesma posição do valgo, com as mãos invertidas.", "alterado": "Abertura lateral excessiva sem ponto final firme.", "significado": "Lesão do LCL (menos comum que a do LCM).", "slide": 26, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "McMurray", "epo": "McMurray", "como": "Decúbito dorsal. Segure o calcanhar e leve o joelho à flexão máxima; palpe as interlinhas. Menisco medial: rotação externa com valgo, estendendo. Menisco lateral: rotação interna com varo, estendendo.", "alterado": "Estalido palpável com dor durante a extensão.", "significado": "Lesão meniscal no compartimento testado. Estalido indolor isolado é inespecífico.", "slide": 27, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Apley (compressão e distração)", "epo": "Apley", "como": "Decúbito ventral, joelho a 90 graus. Compressão com rotação da tíbia; distração com tração da perna para cima e repetição das rotações.", "alterado": "Dor ou estalido na compressão; dor na distração.", "significado": "Compressão: meniscos (rotação externa, medial; rotação interna, lateral). Distração: colaterais (rotação externa, LCM; rotação interna, LCL).", "slide": 28, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Força contra resistência (tornozelo)", "epo": "", "como": "Estabilize a perna. Resista à dorsiflexão, à flexão plantar, à inversão e à eversão, graduando de 0 a 5.", "alterado": "Dor com força preservada no passivo, ou fraqueza indolor.", "significado": "Dor aguda inibe o esforço e simula paresia. Fraqueza indolor sugere causa neurológica.", "slide": 31, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Thompson", "epo": "Thompson", "como": "Decúbito ventral, com os pés pendentes para fora da maca ou com o joelho fletido a 90 graus (ou ajoelhado em uma cadeira). Comprima o ventre do tríceps sural, compare com o lado oposto e observe a flexão plantar.", "alterado": "Ausência de flexão plantar à compressão.", "significado": "Ruptura do tendão do calcâneo. Flexão plantar ativa preservada não afasta ruptura. Sinônimos: Simmonds e Thompson-Doherty.", "slide": 32, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Compressão lateral das MCF", "epo": "", "como": "Comprima lateralmente as metacarpofalângicas, com as mãos relaxadas.", "alterado": "Dor localizada nas MCF.", "significado": "Triagem de sinovite (ex.: AR). Não é diagnóstico.", "slide": 38, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Observação da marcha", "epo": "", "como": "Observe entrada, retorno, mudança de direção e base de apoio, com o paciente caminhando.", "alterado": "Encurtamento do apoio de um lado, queda da pelve, passos curtos, pé caído, oscilação bilateral.", "significado": "Antálgica (encurta o apoio doloroso); Trendelenburg (pelve); parkinsoniana (passos curtos); escarvante (pé caído, L5 ou fibular); anserina (miopatia, fraqueza bilateral).", "slide": 39, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Regras de Ottawa (tornozelo e pé)", "epo": "", "como": "Palpe a borda posterior e a ponta dos maléolos, a base do quinto metatarso e o navicular. Verifique se a pessoa dá 4 passos.", "alterado": "Dor à palpação em qualquer desses pontos, ou incapacidade de dar 4 passos.", "significado": "Indica radiografia após trauma de tornozelo ou pé.", "slide": 41, "pdf": "pdf/aula-08.pdf", "aula": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "aulaId": "aula-08", "grupo": "mmii"}, {"nome": "Babinski (reflexo cutâneo-plantar)", "epo": "Babinski", "como": "Estímulo na borda lateral da planta do pé, com o hálux observado.", "alterado": "Extensão do hálux.", "significado": "Sinal de neurônio motor superior: mielopatia cervical.", "slide": 11, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Hoffmann", "epo": "Hoffmann", "como": "Flexão rápida do dedo médio do examinado; observar o polegar e o indicador.", "alterado": "Flexão reflexa do polegar e do indicador.", "significado": "Sinal de neurônio motor superior cervical.", "slide": 11, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Lhermitte", "epo": "Lhermitte", "como": "Flexão anterior passiva do pescoço.", "alterado": "Choque elétrico descendente pela coluna ou membros.", "significado": "Sugere compressão medular cervical.", "slide": 11, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Força por miótomo (dorsiflexão, inversão, flexão plantar, extensão do hálux)", "epo": "", "como": "Comparar os dois lados: dorsiflexão do pé (L5), inversão (L4), flexão plantar (S1), extensão do hálux.", "alterado": "Fraqueza em um miótomo específico.", "significado": "Localiza a raiz acometida junto com o reflexo.", "slide": 15, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Reflexos patelar e aquileu", "epo": "", "como": "Percussão do tendão patelar (L4) e do tendão de Aquiles (S1), comparando os lados.", "alterado": "Reflexo diminuído ou abolido.", "significado": "Confirma a raiz com déficit de força e dor.", "slide": 15, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Reflexos bicipital, braquiorradial e tricipital", "epo": "", "como": "Percussão do tendão do bíceps (C5), do braquiorradial (C6) e do tríceps (C7).", "alterado": "Reflexo diminuído.", "significado": "Localização de raiz cervical.", "slide": 17, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Sensibilidade por dermátomo e anestesia em sela", "epo": "", "como": "Tato leve e pinprick por dermátomo; investigar a região perineal (sela).", "alterado": "Hipoestesia no dermátomo; anestesia em sela.", "significado": "Sensibilidade por raiz; anestesia em sela é sinal de cauda equina.", "slide": 18, "pdf": "pdf/aula-08-1.pdf", "aula": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "aulaId": "aula-08-1", "grupo": "neuro"}, {"nome": "Palpação de Bartholin e ordenha de Skene", "epo": "Bartholin, Skene", "como": "Palpação bidigital às 4 e 8 horas; ordenha no teto vaginal para exteriorizar secreção pelo meato.", "alterado": "Tumefação dolorosa, calor, rubor ou secreção purulenta.", "significado": "Cisto de Bartholin (indolor) versus abscesso (dor intensa, calor e rubor); infecção de Skene.", "slide": 34, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Inspeção dinâmica com Valsalva", "epo": "Valsalva", "como": "Pedir tosse ou esforço de evacuação, com a paciente em litotomia ou em pé.", "alterado": "Protrusão da parede anterior, posterior ou descida do colo, com perda urinária.", "significado": "Cistocele ou cistouretrocele (anterior), retocele (posterior), prolapso uterino (ápice) e incontinência de esforço.", "slide": 37, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Introdução do espéculo", "epo": "Collins", "como": "Testar o tamanho; aquecer com água, sem gel; introduzir fechado e oblíquo; girar para a horizontal e avançar totalmente; fixar e iluminar o colo.", "alterado": "Dor, colo não exposto ou amostra inviável.", "significado": "Erros comuns: gel antes da coleta ou abrir as lâminas antes de alcançar o fundo.", "slide": 42, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Teste de Schiller e ácido acético", "epo": "Schiller", "como": "Aplicar iodo (Schiller) ou ácido acético a 5% no colo; azul de toluidina na vulva (teste de Collins).", "alterado": "Áreas iodo-negativas, acetobrancas ou azuladas.", "significado": "Risco de atipia celular: exige biópsia dirigida.", "slide": 49, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Testes do corrimento à beira do leito", "epo": "", "como": "Medir o pH; teste das aminas com KOH; exame a fresco com soro fisiológico e KOH.", "alterado": "pH maior que 4,5, odor de peixe, clue cells, flagelados ou hifas.", "significado": "Vaginose bacteriana, tricomoníase ou candidíase, sem esperar cultura.", "slide": 56, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Coleta cervical com espátula de Ayres e escova", "epo": "Ayres, Campos da Paz", "como": "Espátula de Ayres girando 360 graus na ectocérvice; escova endocervical colhendo no canal.", "alterado": "Resultado do DNA-HPV (16 ou 18, outros tipos, não detectado).", "significado": "Conduta conforme genotipagem: colposcopia, citologia reflexa ou repetir em 5 anos.", "slide": 57, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Toque bimanual", "epo": "", "como": "Indicador e médio na vagina, pressão no períneo e mão abdominal acima da sínfise; mobilizar o colo; elevar o útero contra a mão abdominal.", "alterado": "Dor à mobilização do colo, nodularidade nos fórnices, massa anexial.", "significado": "DIP, gravidez ectópica ou apendicite (dor); endometriose (nodularidade); registrar o útero com parâmetros.", "slide": 59, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Toque retovaginal", "epo": "Douglas", "como": "Trocar a luva; indicador na vagina e médio no reto; avisar sobre a sensação de evacuar.", "alterado": "Nodularidade do septo, massa no fundo de saco de Douglas, útero retrovertido fixo.", "significado": "Alcança o que o toque vaginal não alcança (ligamentos uterossacros, septo e fundo de saco).", "slide": 64, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Manobra de Weibel", "epo": "Weibel", "como": "Mobilizar a massa pelo abdome durante o toque bimanual.", "alterado": "O colo acompanha o movimento ou permanece estacionário.", "significado": "Colo acompanha: massa uterina (mioma); estacionário: massa anexial (cisto).", "slide": 67, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Manobra de Hegar com pinça de Pozzi", "epo": "Hegar, Pozzi", "como": "Ao espéculo, apreender o lábio anterior do colo com a pinça de Pozzi e mobilizar a massa pelo abdome.", "alterado": "O cabo da pinça se move junto com a massa.", "significado": "Massa de origem uterina; manobra instrumental que exige técnica rigorosa e consentimento.", "slide": 68, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Avaliação da força do assoalho pélvico", "epo": "", "como": "Solicitar contração máxima ao redor dos dedos; manter por 3 segundos; tosse ou Valsalva durante a palpação.", "alterado": "Compressão fraca, recrutamento de abdome, adutores ou glúteos, pontos-gatilho dolorosos, perda de urina.", "significado": "Espasmo, fraqueza ou disfunção do assoalho pélvico.", "slide": 69, "pdf": "pdf/aula-09-1.pdf", "aula": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "aulaId": "aula-09-1", "grupo": "gufem"}, {"nome": "Ordenha uretral", "epo": "", "como": "Expressão firme da base do pênis até a glande.", "alterado": "Secreção uretral.", "significado": "Fundamental se há queixa de secreção não visível em repouso; Gram e cultura confirmam a etiologia.", "slide": 32, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Compressão suave da glande", "epo": "", "como": "Comprimir a glande para abrir o meato uretral e inspecionar.", "alterado": "Estenose, secreção, posição anômala do meato.", "significado": "Estenose de meato, hipospádia, uretrite.", "slide": 33, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Palpação do testículo e do epidídimo (unimanual)", "epo": "", "como": "Palpar entre polegar e dois dedos, sem apertar, sempre comparando os lados.", "alterado": "Nódulo duro e indolor; epidídimo doloroso.", "significado": "Nódulo duro é câncer até prova em contrário; epididimite pela dor.", "slide": 37, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Palpar acima da massa escrotal", "epo": "", "como": "Tentar palpar a alça acima da massa, em direção ao anel.", "alterado": "Dedos conseguem palpar acima.", "significado": "Hidrocele; hérnia escrotal não permite.", "slide": 44, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Toque retal: técnica passo a passo", "epo": "", "como": "Inspecionar a região perianal; apoiar a polpa do dedo e aguardar o relaxamento; introduzir em direção ao umbigo; avaliar tônus e ampola; girar o dedo para a face posterior da próstata; inspecionar a luva.", "alterado": "Tônus alterado, massa na ampola, nódulo, assimetria ou dor.", "significado": "Triagem prostática; o toque normal não exclui câncer; nódulo duro exige investigação urológica.", "slide": 57, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Toque retal (técnica estruturada)", "epo": "", "como": "Decúbito lateral esquerdo ou genupeitoral; apoiar e esperar relaxamento; introduzir em direção ao umbigo; girar o dedo.", "alterado": "Tônus alterado, massa na ampola, nódulo ou assimetria prostática.", "significado": "Triagem prostática; nódulo duro exige investigação urológica.", "slide": 58, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Reflexo cremastérico", "epo": "", "como": "Paciente em decúbito dorsal; tocar ou pinçar levemente a face superomedial da coxa e observar o testículo do mesmo lado.", "alterado": "Ausência de elevação ipsilateral.", "significado": "Na torção, quase sempre ausente (raízes L1 a L2); reflexo presente sugere, mas não exclui torção.", "slide": 67, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Sinal de Prehn", "epo": "Prehn", "como": "Elevar delicadamente o testículo em direção ao anel inguinal, em decúbito.", "alterado": "Dor não alivia.", "significado": "Pensar em torção (baixa confiabilidade).", "slide": 68, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Sinal de Brunzel", "epo": "Brunzel", "como": "Inspeção visual comparativa, com o paciente em pé e deitado.", "alterado": "Testículo afetado mais elevado, com eixo horizontal.", "significado": "Sugere torção testicular; examine o lado sadio, pois a deformidade em badalo de sino é bilateral em até 80%.", "slide": 69, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Sinal do ponto azul", "epo": "Morgagni", "como": "Inspeção do polo superior do testículo com a pele esticada.", "alterado": "Ponto azulado ou necrótico visível por transparência.", "significado": "Torção da hidátide de Morgagni; na dúvida, conduzir como torção testicular.", "slide": 70, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Transiluminação do escroto", "epo": "", "como": "Sala escura; lanterna de foco direto atrás do escroto.", "alterado": "Brilho vermelho (transilumina) ou sombra opaca (não transilumina).", "significado": "Transilumina: massa cística (hidrocele, cisto de epidídimo). Não transilumina: massa sólida (tumor, orquiepididimite, torção, hematocele, maioria das hérnias). Hidrocele irredutível no anel pode ser indistinguível de hérnia estrangulada.", "slide": 71, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Manobra de Chevassu", "epo": "Chevassu", "como": "Pinçar o epidídimo entre indicador e polegar, deslizando de baixo para cima e de frente para trás ao longo das faces do testículo.", "alterado": "Aumento regular e difuso; irregular e multinodular; localizado.", "significado": "Regular e difuso: epididimite aguda. Irregular ou multinodular: tuberculose genitourinária. Localizado: cistos (cabeça ou corpo) ou lesões inespecíficas (cauda).", "slide": 72, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Distorção manual do testículo", "epo": "", "como": "Girar o testículo de medial para lateral (abrir o livro), muitas vezes mais de 360 graus.", "alterado": "Alívio da dor e retorno do fluxo ao Doppler.", "significado": "Medida temporária de emergência na torção.", "slide": 73, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Escore TWIST", "epo": "TWIST", "como": "Somar: edema testicular intenso (2), testículo endurecido (2), cremastérico ausente (1), náuseas ou vômitos (1), testículo elevado (1).", "alterado": "5 a 7 pontos, alto risco; 3 a 4, intermediário; 0 a 2, baixo.", "significado": "Alto risco: cirurgia imediata, sem atrasar pelo Doppler; intermediário: Doppler imediato; baixo: diagnósticos alternativos.", "slide": 74, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Retração e devolução do prepúcio", "epo": "", "como": "Retrair o prepúcio para inspecionar a glande; devolver SEMPRE em seguida.", "alterado": "Prepúcio que não retorna e edema da glande.", "significado": "Parafimose, urgência.", "slide": 80, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Palpação do corpo do pênis e ordenha uretral", "epo": "", "como": "Palpar o corpo entre polegar e dois dedos; ordenhar a uretra se houver queixa de secreção.", "alterado": "Placa dorsal, induração ventral, secreção.", "significado": "Peyronie; estenose ou carcinoma; uretrite.", "slide": 80, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Pesquisa de hérnia inguinal (em pé, com tosse)", "epo": "", "como": "Invaginar a pele escrotal até o anel inguinal superficial; pedir tosse.", "alterado": "Impulso contra o dedo.", "significado": "Hérnia inguinal indireta, direta; femoral pela palpação medial à artéria femoral.", "slide": 81, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}, {"nome": "Varicocele em pé com Valsalva", "epo": "Valsalva", "como": "Em pé, palpar o funículo cerca de 2 cm acima do testículo com Valsalva.", "alterado": "Saco de vermes que não colapsa.", "significado": "Varicocele; investigar se não colapsa ou surge após os 40 anos.", "slide": 81, "pdf": "pdf/aula-09.pdf", "aula": "Aula 9 - Semiologia do sistema genitourinário masculino", "aulaId": "aula-09", "grupo": "gumasc"}], "quiz": [{"id": 1, "nivel": "dificil", "enunciado": "Mulher de 52 anos com dor cervical e formigamento que irradia para o braço direito. O examinador, por trás, inclina a cabeça para o lado sintomático e aplica compressão axial. A dor irradia para o mesmo membro superior. Qual manobra foi realizada, e por que a dor cervical local isolada não basta para o diagnóstico?", "alternativas": ["Spurling", "SCORTEN", "Vitropressão", "Palpação de elevação", "Exame ativo de mucosas"], "gabarito": "A", "justificativa": "Manobra: Spurling. Achado alterado: Reprodução de dor ou parestesia irradiada para o membro superior do mesmo lado. Significado: Compressão de raiz cervical. Dor cervical local isolada é inespecífica. Não fazer com suspeita de fratura ou instabilidade. Ver slide 6 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 6, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 2, "nivel": "dificil", "enunciado": "Homem de 30 anos, após picada de abelha, apresenta voz rouca e sibilância. Antes de qualquer decisão, a equipe avalia via aérea, respiração, circulação e consciência em paralelo. Qual avaliação é essa, e qual achado exige adrenalina imediata sem atraso?", "alternativas": ["Pesquisa de dor cutânea desproporcional", "Palpação de temperatura e umidade", "Teste de atrito (dermografismo)", "Avaliação de via aérea, respiração e circulação (ABC)", "Exame básico do ombro (inspeção, palpação e mobilidade)"], "gabarito": "D", "justificativa": "Manobra: Avaliação de via aérea, respiração e circulação (ABC). Achado alterado: Estridor, voz alterada, sibilância, hipotensão ou síncope. Significado: Sinais que não se pode perder na anafilaxia: adrenalina IM sem atraso. Ver slide 9 do professor.", "tecnica": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "slide": 9, "pdf": "pdf/aula-06.pdf", "tipo": "nome"}, {"id": 3, "nivel": "dificil", "enunciado": "Mulher com placa vermelha no antebraço esquerdo. Ao comparar os dois lados, o examinador encontra diferença de calor e umidade, sem relato de febre. Qual manobra revela a alteração de perfusão local, e o que o registro da região acrescenta?", "alternativas": ["Palpação de temperatura e umidade", "Classificação pelo descolamento", "Teste de atrito (dermografismo)", "Pesquisa de dor cutânea desproporcional", "Prega cutânea (turgor)"], "gabarito": "A", "justificativa": "Manobra: Palpação de temperatura e umidade. Achado alterado: Assimetria de temperatura ou umidade. Significado: Alteração de perfusão ou de processo local; registre a região. Ver slide 10 do professor.", "tecnica": "Aula 6.1 - Semiologia tegumentar", "slide": 10, "pdf": "pdf/aula-06-1.pdf", "tipo": "nome"}, {"id": 4, "nivel": "dificil", "enunciado": "Idoso de 80 anos, em perda de peso e com ingestão reduzida. A pele do dorso da mão, ao ser pinçada e solta, demora mais para voltar à posição. Qual manobra é essa, e por que o achado deve ser interpretado com idade e perda de peso?", "alternativas": ["Exame ativo de mucosas", "Palpação de elevação", "Classificação pelo descolamento", "Prega cutânea (turgor)", "Teste de atrito (dermografismo)"], "gabarito": "D", "justificativa": "Manobra: Prega cutânea (turgor). Achado alterado: A prega persiste por mais tempo que o normal. Significado: Turgor diminuído, a interpretar no contexto: desidratação, idade e perda de peso. Ver slide 14 do professor.", "tecnica": "Aula 6.1 - Semiologia tegumentar", "slide": 14, "pdf": "pdf/aula-06-1.pdf", "tipo": "nome"}, {"id": 5, "nivel": "dificil", "enunciado": "Homem com rash extenso e início de bolhas. A dor à palpação é muito maior do que a área aparente sugere. O examinador não deve tranquilizar pelo tamanho da lesão. Qual manobra descreve essa dor, e qual diagnóstico ela sugere?", "alternativas": ["Palpação de temperatura e umidade", "Pesquisa de dor cutânea desproporcional", "Teste de atrito (dermografismo)", "Classificação pelo descolamento", "Avaliação de via aérea, respiração e circulação (ABC)"], "gabarito": "B", "justificativa": "Manobra: Pesquisa de dor cutânea desproporcional. Achado alterado: Dor intensa desproporcional ao que se vê. Significado: Pista de SSJ/NET; pede avaliação dirigida, sem tranquilizar pelo tamanho. Ver slide 19 do professor.", "tecnica": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "slide": 19, "pdf": "pdf/aula-06.pdf", "tipo": "nome"}, {"id": 6, "nivel": "dificil", "enunciado": "Paciente com febre, erosões orais dolorosas e ardor ocular. Ao examinar as mucosas de forma ativa, o médico encontra dificuldade para ingerir líquidos e fotofobia. Qual exame é esse, e qual conduta deve seguir imediatamente?", "alternativas": ["Prega cutânea (turgor)", "Exame ativo de mucosas", "Palpação de elevação", "Classificação pelo descolamento", "Teste de atrito (dermografismo)"], "gabarito": "B", "justificativa": "Manobra: Exame ativo de mucosas. Achado alterado: Erosões dolorosas, fotofobia, ardor ocular, dificuldade para ingerir. Significado: Suspeita de SSJ/NET: avaliação oftalmológica precoce e internação. Ver slide 20 do professor.", "tecnica": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "slide": 20, "pdf": "pdf/aula-06.pdf", "tipo": "nome"}, {"id": 7, "nivel": "dificil", "enunciado": "Homem com lesões cutâneas extensas após uso de fármaco. A área descolada corresponde a 15% da superfície corporal, com sinal de Nikolsky positivo. Qual classificação se aplica pelo descolamento, e qual é a implicação para a admissão?", "alternativas": ["Teste de atrito (dermografismo)", "Classificação pelo descolamento", "Palpação de temperatura e umidade", "Pesquisa de dor cutânea desproporcional", "Prega cutânea (turgor)"], "gabarito": "B", "justificativa": "Manobra: Classificação pelo descolamento. Achado alterado: Descolamento de 10 a 30% (sobreposição) ou mais de 30% (NET). Significado: SSJ abaixo de 10%. A classificação orienta a gravidade e a admissão. Ver slide 21 do professor.", "tecnica": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "slide": 21, "pdf": "pdf/aula-06.pdf", "tipo": "nome"}, {"id": 8, "nivel": "dificil", "enunciado": "Paciente com lesão cutânea que, à inspeção, parece plana. Ao toque, percebe-se um relevo com consistência sólida. O examinador precisa decidir se a lesão é mácula ou elevada. Qual manobra confirma a elevação?", "alternativas": ["Exame ativo de mucosas", "Prega cutânea (turgor)", "Palpação de elevação", "Vitropressão", "Classificação pelo descolamento"], "gabarito": "C", "justificativa": "Manobra: Palpação de elevação. Achado alterado: Relevo palpável, com ou sem consistência sólida. Significado: Mácula (plana) versus pápula, placa ou nódulo (elevados). Só o tato confirma elevação. Ver slide 25 do professor.", "tecnica": "Aula 6.1 - Semiologia tegumentar", "slide": 25, "pdf": "pdf/aula-06-1.pdf", "tipo": "nome"}, {"id": 9, "nivel": "dificil", "enunciado": "Paciente com necrólise epidérmica após fármaco. Há idade avançada, câncer associado, frequência cardíaca alta e glicemia elevada. Qual escore estima a mortalidade e orienta a admissão em centro de queimados?", "alternativas": ["Spurling", "Vitropressão", "SCORTEN", "Palpação de elevação", "Exame ativo de mucosas"], "gabarito": "C", "justificativa": "Manobra: SCORTEN. Achado alterado: Escore alto (quanto mais critérios, maior a mortalidade estimada). Significado: Prognóstico e apoio para a admissão em terapia intensiva ou centro de queimados. Ver slide 25 do professor.", "tecnica": "Aula 6 - Síndromes: anafilaxia, SSJ e NET", "slide": 25, "pdf": "pdf/aula-06.pdf", "tipo": "nome"}, {"id": 10, "nivel": "dificil", "enunciado": "Criança com lesões purpúreas no membro inferior após febre. Ao aplicar uma lâmina de vidro sobre a lesão, a cor não some. Qual manobra é essa, e o que diferenciaria esse achado de um eritema?", "alternativas": ["Spurling", "SCORTEN", "Palpação de elevação", "Vitropressão", "Exame ativo de mucosas"], "gabarito": "D", "justificativa": "Manobra: Vitropressão. Achado alterado: A cor persiste sob a lâmina (não empalidece). Significado: Púrpura, por extravasamento sanguíneo. Se empalidece, é eritema, por vasodilatação. Ver slide 26 do professor.", "tecnica": "Aula 6.1 - Semiologia tegumentar", "slide": 26, "pdf": "pdf/aula-06-1.pdf", "tipo": "nome"}, {"id": 11, "nivel": "dificil", "enunciado": "Paciente com urticas lineares no trajeto onde a pele foi arranhada, sem coceira espontânea. O médico quer confirmar a forma de urticária. Qual manobra reproduz esse achado, e o que a duração das lesões acrescenta?", "alternativas": ["Classificação pelo descolamento", "Palpação de temperatura e umidade", "Pesquisa de dor cutânea desproporcional", "Exame ativo de mucosas", "Teste de atrito (dermografismo)"], "gabarito": "E", "justificativa": "Manobra: Teste de atrito (dermografismo). Achado alterado: Urticas lineares no trajeto do atrito. Significado: Dermografismo: urticas após atrito. Forma de urticária; observe a duração das lesões. Ver slide 31 do professor.", "tecnica": "Aula 6.1 - Semiologia tegumentar", "slide": 31, "pdf": "pdf/aula-06-1.pdf", "tipo": "nome"}, {"id": 12, "nivel": "dificil", "enunciado": "Homem de 35 anos com dor lombar inflamatória e rigidez matinal. Ao pedir que o paciente faça inspiração profunda, o examinador nota expansão torácica reduzida. Qual manobra mede essa expansão, e qual doença o achado sugere?", "alternativas": ["Classificação de Tanner", "Expansibilidade torácica", "Contração do peitoral", "Inspeção estática", "Artrocentese diagnóstica"], "gabarito": "B", "justificativa": "Manobra: Expansibilidade torácica. Achado alterado: Expansibilidade reduzida. Significado: Expansibilidade torácica reduzida faz parte do quadro da espondilite anquilosante (slide 8). Ver slide 8 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 8, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 13, "nivel": "dificil", "enunciado": "Adolescente de 13 anos com desenvolvimento das mamas e dos pelos pubianos fora da faixa esperada para a idade. Qual classificação puberal avalia esse desenvolvimento, e qual é seu papel na avaliação?", "alternativas": ["Expansibilidade torácica", "Classificação de Tanner", "Contração do peitoral", "Expressão papilar", "Inspeção estática"], "gabarito": "B", "justificativa": "Manobra: Classificação de Tanner. Achado alterado: Desenvolvimento fora da faixa esperada. Significado: Avalia o desenvolvimento puberal. Ver slide 11 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 11, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 14, "nivel": "dificil", "enunciado": "Mulher de 55 anos com nódulo mamário e retração do mamilo visível em repouso, com casca de laranja no contorno. Qual exame inicial é esse, e por que ele deve ser feito antes de qualquer manobra dinâmica?", "alternativas": ["Expressão papilar", "Contração do peitoral", "Inspeção estática", "Mama pendente", "Classificação de Tanner"], "gabarito": "C", "justificativa": "Manobra: Inspeção estática. Achado alterado: Assimetria, retração, edema, casca de laranja, retração do mamilo. Significado: Sinais visíveis de alerta exigem referência urgente. Ver slide 19 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 19, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 15, "nivel": "dificil", "enunciado": "Mulher com retração da pele mamária que aparece somente quando ela levanta os braços. Em repouso, a mama parece normal. Qual manobra revela essa alteração, e qual estrutura ela estira?", "alternativas": ["Palpação mamária em faixas verticais", "Palpação das axilas (deslizante)", "Inspeção dinâmica com braços elevados", "Palpação das fossas supra e infraclaviculares", "Palpação com a técnica de Velpeau ou Bloodgood"], "gabarito": "C", "justificativa": "Manobra: Inspeção dinâmica com braços elevados. Achado alterado: Retração, depressão ou assimetria que não aparecem em repouso. Significado: Estira os ligamentos de Cooper e revela fixações. Ver slide 20 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 20, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 16, "nivel": "dificil", "enunciado": "Paciente com nódulo mamário que, ao contrair o peitoral, fica mais fixo e não se move com o músculo. Qual manobra testa essa fixação, e de qual estrutura o nódulo está aderido?", "alternativas": ["Classificação de Tanner", "Expansibilidade torácica", "Expressão papilar", "Inspeção estática", "Contração do peitoral"], "gabarito": "E", "justificativa": "Manobra: Contração do peitoral. Achado alterado: Retração que se acentua; nódulo que se fixa à fáscia. Significado: Testa a fixação do nódulo à fáscia peitoral. Ver slide 21 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 21, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 17, "nivel": "dificil", "enunciado": "Mulher com mama volumosa e pendular, em que o exame em repouso não revela fixação. Qual manobra deve ser feita nesse caso, e o que ela busca?", "alternativas": ["Expressão papilar", "Inspeção estática", "Contração do peitoral", "Classificação de Tanner", "Mama pendente"], "gabarito": "E", "justificativa": "Manobra: Mama pendente. Achado alterado: Fixações profundas, assimetria de contorno ou desvio do mamilo. Significado: Essencial em mamas volumosas ou pendulares. Ver slide 21 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 21, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 18, "nivel": "dificil", "enunciado": "Mulher com nódulo axilar. O examinador desliza os dedos sobre a região e encontra linfonodo de 1,5 cm, duro e fixo ao plano. Qual manobra é essa, e qual é a conduta diante desse achado?", "alternativas": ["Palpação das axilas (deslizante)", "Palpação mamária em faixas verticais", "Inspeção dinâmica com braços elevados", "Expansibilidade torácica", "Classificação de Tanner"], "gabarito": "A", "justificativa": "Manobra: Palpação das axilas (deslizante). Achado alterado: Linfonodo de 1 cm ou mais, duro, fixo ou coalescente. Significado: Linfadenopatia axilar suspeita: encaminhamento urgente. Ver slide 25 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 25, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 19, "nivel": "dificil", "enunciado": "Mulher com linfonodo na fossa supraclavicular direita, duro e fixo. Qual manobra palpa essa região, e o que o achado sugere?", "alternativas": ["Palpação com a técnica de Velpeau ou Bloodgood", "Inspeção dinâmica com braços elevados", "Palpação das fossas supra e infraclaviculares", "Palpação mamária em faixas verticais", "Palpação das axilas (deslizante)"], "gabarito": "C", "justificativa": "Manobra: Palpação das fossas supra e infraclaviculares. Achado alterado: Linfonodo supraclavicular ou infraclavicular duro ou fixo. Significado: Metástase suspeita. Ver slide 26 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 26, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 20, "nivel": "dificil", "enunciado": "Mulher de 40 anos com área de espessamento na mama. O examinador usa uma técnica clássica de palpação, com o paciente em decúbito ou com o braço atrás da cabeça. Qual técnica é essa, e para que ela serve?", "alternativas": ["Palpação das fossas supra e infraclaviculares", "Inspeção dinâmica com braços elevados", "Palpação mamária em faixas verticais", "Palpação com a técnica de Velpeau ou Bloodgood", "Coleta cervical com espátula de Ayres e escova"], "gabarito": "D", "justificativa": "Manobra: Palpação com a técnica de Velpeau ou Bloodgood. Achado alterado: Nódulo ou área de espessamento. Significado: Técnicas clássicas de palpação. Ver slide 28 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 28, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 21, "nivel": "dificil", "enunciado": "Mulher com nódulo mamário endurecido, de limites imprecisos e superfície irregular. O médico usa a técnica de faixas para cobrir toda a mama, sistematicamente. Qual manobra é essa, e por que ela é considerada padrão para massas dominantes?", "alternativas": ["Palpação mamária em faixas verticais", "Inspeção dinâmica com braços elevados", "Palpação das axilas (deslizante)", "Palpação das fossas supra e infraclaviculares", "Palpação com a técnica de Velpeau ou Bloodgood"], "gabarito": "A", "justificativa": "Manobra: Palpação mamária em faixas verticais. Achado alterado: Nódulo endurecido, irregular, de limites imprecisos. Significado: Padrão ouro para massas dominantes. Ver slide 29 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 29, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 22, "nivel": "dificil", "enunciado": "Mulher com secreção mamilar de um único ducto e papila espessa, que não se deforma ao ser comprimida. Qual manobra avalia essa papila, e o que o achado sugere?", "alternativas": ["Inspeção estática", "Mama pendente", "Expressão papilar", "Contração do peitoral", "Classificação de Tanner"], "gabarito": "C", "justificativa": "Manobra: Expressão papilar. Achado alterado: Papila espessa e inelástica; secreção de ducto único. Significado: Papila inelástica: forte suspeita de malignidade subjacente. Ver slide 30 do professor.", "tecnica": "Aula 9.2 - Semiologia das mamas", "slide": 30, "pdf": "pdf/aula-09-2.pdf", "tipo": "nome"}, {"id": 23, "nivel": "dificil", "enunciado": "Paciente com dor e inchaço de apenas um joelho há três dias. O médico precisa definir o padrão articular antes de decidir a investigação. Qual manobra conta as articulações afetadas, e qual padrão a monoartrite representa?", "alternativas": ["Matriz de diferenciação cinética", "Palpação do aumento de volume", "Contagem e distribuição articular", "Finkelstein (De Quervain)", "Toque retal (técnica estruturada)"], "gabarito": "C", "justificativa": "Manobra: Contagem e distribuição articular. Achado alterado: 1 articulação (monoartrite), 2 a 4 (oligoartrite), 5 ou mais (poliartrite). Significado: Define o padrão sindrômico e a prioridade diferencial. Ver slide 5 do professor.", "tecnica": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "slide": 5, "pdf": "pdf/aula-07.pdf", "tipo": "nome"}, {"id": 24, "nivel": "dificil", "enunciado": "Homem de 28 anos com artrite de tornozelo, psoríase no couro cabeludo e diarreia crônica. Qual manobra organiza a pesquisa de manifestações fora das articulações, e que diagnósticos ela aponta?", "alternativas": ["Flexão resistida do punho (epicôndilo medial)", "Exame básico do ombro (inspeção, palpação e mobilidade)", "Contagem e distribuição articular", "Matriz de diferenciação cinética", "Investigação de manifestações extra-articulares"], "gabarito": "E", "justificativa": "Manobra: Investigação de manifestações extra-articulares. Achado alterado: Olho vermelho doloroso, psoríase, diarreia crônica, uretrite ou fenômeno de Raynaud. Significado: Sugere espondiloartrite, artrite psoriásica, doença inflamatória intestinal ou colagenose. Ver slide 8 do professor.", "tecnica": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "slide": 8, "pdf": "pdf/aula-07.pdf", "tipo": "nome"}, {"id": 25, "nivel": "dificil", "enunciado": "Paciente com monoartrite inflamatória aguda de joelho, em que a história não confirma etiologia. Qual procedimento diagnóstico é indicado e quais achados confirmam infecção ou cristais?", "alternativas": ["Finkelstein (De Quervain)", "Palpação do aumento de volume", "Artrocentese diagnóstica", "Adução cruzada (AC)", "Matriz de diferenciação cinética"], "gabarito": "C", "justificativa": "Manobra: Artrocentese diagnóstica. Achado alterado: Contagem celular alta, cultura positiva ou cristais específicos. Significado: Confirma infecção ou cristais. Nenhum achado clínico isolado substitui a artrocentese em monoartrite aguda inflamatória. Ver slide 10 do professor.", "tecnica": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "slide": 10, "pdf": "pdf/aula-07.pdf", "tipo": "nome"}, {"id": 26, "nivel": "dificil", "enunciado": "Homem de 60 anos com dor no ombro e limitação de movimento. Antes dos testes especiais, o examinador avalia inspeção, palpação e mobilidade. Qual é essa avaliação inicial, e por que ela deve preceder os testes?", "alternativas": ["Investigação de manifestações extra-articulares", "Flexão resistida do punho (epicôndilo medial)", "Contagem e distribuição articular", "Força por miótomo (dorsiflexão, inversão, flexão plantar, extensão do hálux)", "Exame básico do ombro (inspeção, palpação e mobilidade)"], "gabarito": "E", "justificativa": "Manobra: Exame básico do ombro (inspeção, palpação e mobilidade). Achado alterado: Assimetria, dor palpatória focal, limitação de arco. Significado: Mapeia a função antes dos testes especiais. Ver slide 18 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 18, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 27, "nivel": "dificil", "enunciado": "Paciente com dor que surge em um arco intermediário de elevação do braço, e não no fim do movimento. Qual manobra reproduz esse padrão, e qual estrutura é comprimida?", "alternativas": ["Adução cruzada (AC)", "Hawkins", "Arco doloroso", "Gerber", "Phalen"], "gabarito": "C", "justificativa": "Manobra: Arco doloroso. Achado alterado: Dor no arco intermediário ou no arco final extremo. Significado: Pinçamento subacromial (intermediário) ou articulação AC (final). Ver slide 19 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 19, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 28, "nivel": "dificil", "enunciado": "Mulher com dor no ombro durante elevação forçada do braço. O examinador eleva o membro com o cotovelo em extensão e a mão em pronação. Qual manobra provoca o pinçamento subacromial?", "alternativas": ["Jobe", "Cozen", "Neer", "Patte", "Tinel"], "gabarito": "C", "justificativa": "Manobra: Neer. Achado alterado: Dor habitual reproduzida. Significado: Pinçamento da grande tuberosidade contra o arco coracoacromial. Ver slide 20 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 20, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 29, "nivel": "dificil", "enunciado": "Paciente com dor subacromial que aparece quando o cotovelo é levado a 90 graus e o ombro é fletido e rodado internamente. Qual manobra é essa, e em que combinação ela é usada?", "alternativas": ["Gerber", "Phalen", "Speed", "Hawkins", "Lachman"], "gabarito": "D", "justificativa": "Manobra: Hawkins. Achado alterado: Dor subacromial habitual reproduzida. Significado: Compõe o somatório com Neer e o arco doloroso. Ver slide 21 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 21, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 30, "nivel": "dificil", "enunciado": "Homem com dor ao erguer o braço para o lado, em que o examinador mantém a força contra resistência. Qual manobra testa o supraespinhoso, e como ela diferencia dor de fraqueza?", "alternativas": ["Neer", "Tinel", "Cozen", "Patte", "Jobe"], "gabarito": "E", "justificativa": "Manobra: Jobe. Achado alterado: Dor ou incapacidade de sustentação. Significado: Supraespinhoso. Distinga dor de fraqueza. Ver slide 24 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 24, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 31, "nivel": "dificil", "enunciado": "Paciente com perda de força ao girar o braço para fora contra resistência, e compensação do tronco. Qual manobra testa esse músculo, e qual é o músculo?", "alternativas": ["Cozen", "Tinel", "Speed", "Jobe", "Patte"], "gabarito": "E", "justificativa": "Manobra: Patte. Achado alterado: Perda de força na rotação externa. Significado: Infraespinhoso. Observe a compensação do tronco. Ver slide 25 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 25, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 32, "nivel": "dificil", "enunciado": "Homem que não consegue afastar a mão da coluna lombar, mesmo com ajuda do examinador. Não há rigidez capsular. Qual manobra avalia esse músculo, e qual é o músculo?", "alternativas": ["Phalen", "Hawkins", "Cozen", "Gerber", "Speed"], "gabarito": "D", "justificativa": "Manobra: Gerber. Achado alterado: Incapacidade de afastar a mão. Significado: Subescapular, se não houver rigidez capsular. Ver slide 26 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 26, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 33, "nivel": "dificil", "enunciado": "Paciente com dor no sulco bicipital ao realizar flexão do cotovelo contra resistência, com o antebraço em supinação. Qual manobra é essa, e qual tendão está em questão?", "alternativas": ["Tinel", "Patte", "Speed", "Cozen", "Neer"], "gabarito": "C", "justificativa": "Manobra: Speed. Achado alterado: Dor focal no sulco bicipital. Significado: Tendinopatia da porção longa do bíceps. Ver slide 27 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 27, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 34, "nivel": "dificil", "enunciado": "Paciente com aumento de volume no joelho. Ao palpar, a consistência é elástica e há dor às interlinhas; em outro paciente, a consistência é dura e nodular. Qual manobra diferencia esses achados, e o que cada um indica?", "alternativas": ["Matriz de diferenciação cinética", "Contagem e distribuição articular", "Palpação do aumento de volume", "Finkelstein (De Quervain)", "Artrocentese diagnóstica"], "gabarito": "C", "justificativa": "Manobra: Palpação do aumento de volume. Achado alterado: Consistência elástica ou esponjosa com dor às interlinhas (sinovite); consistência dura e nodular (osteófito). Significado: Diferencia sinovite de proliferação óssea e de edema subcutâneo. Ver slide 27 do professor.", "tecnica": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "slide": 27, "pdf": "pdf/aula-07.pdf", "tipo": "nome"}, {"id": 35, "nivel": "dificil", "enunciado": "Homem com dor ao cruzar o braço sobre o peito, com o examinador aplicando compressão. A dor é pontual na região do acrômio. Qual manobra é essa, e o que a dor posterior por alongamento acrescenta?", "alternativas": ["Adução cruzada (AC)", "Artrocentese diagnóstica", "Finkelstein (De Quervain)", "Arco doloroso", "Palpação do aumento de volume"], "gabarito": "A", "justificativa": "Manobra: Adução cruzada (AC). Achado alterado: Dor pontual na articulação AC. Significado: Patologia AC. Dor posterior por alongamento não é compressão. Ver slide 28 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 28, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 36, "nivel": "dificil", "enunciado": "Paciente com dor no ombro: o movimento passivo está limitado, mas o movimento resistido, contra força, é indolor. Qual matriz orienta essa diferenciação, e o que ela indica sobre a origem da dor?", "alternativas": ["Contagem e distribuição articular", "Matriz de diferenciação cinética", "Palpação do aumento de volume", "Finkelstein (De Quervain)", "Artrocentese diagnóstica"], "gabarito": "B", "justificativa": "Manobra: Matriz de diferenciação cinética. Achado alterado: Passivo limitado com resistido indolor sugere articular (cápsula); passivo preservado com resistido doloroso sugere tendão ou bursa. Significado: Separa doença articular verdadeira de periarticular, e orienta a investigação. Ver slide 30 do professor.", "tecnica": "Aula 7 - Síndromes articulares e raciocínio diagnóstico", "slide": 30, "pdf": "pdf/aula-07.pdf", "tipo": "nome"}, {"id": 37, "nivel": "dificil", "enunciado": "Tenista com dor na face lateral do cotovelo ao extensionar o punho contra resistência. A dor é focal na origem extensora lateral. Qual manobra provoca essa dor?", "alternativas": ["Patte", "Tinel", "Speed", "Cozen", "Gerber"], "gabarito": "D", "justificativa": "Manobra: Cozen. Achado alterado: Dor focada na origem extensora lateral. Significado: Epicondilite lateral. Ver slide 31 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 31, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 38, "nivel": "dificil", "enunciado": "Paciente com dor na face medial do cotovelo ao flexionar o punho contra resistência, com parestesia no quarto e quinto dedos. Qual manobra é essa, e qual nervo exige avaliação?", "alternativas": ["Flexão resistida do punho (epicôndilo medial)", "Investigação de manifestações extra-articulares", "Exame básico do ombro (inspeção, palpação e mobilidade)", "Contagem e distribuição articular", "Matriz de diferenciação cinética"], "gabarito": "A", "justificativa": "Manobra: Flexão resistida do punho (epicôndilo medial). Achado alterado: Dor focal na origem flexora medial; parestesia no 4º e 5º dedos. Significado: Epicondilite medial; parestesia exige avaliação do nervo ulnar. Ver slide 32 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 32, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 39, "nivel": "dificil", "enunciado": "Operária que trabalha com digitação e relata formigamento no polegar, indicador e médio, pior à noite. O examinador mantém o punho em flexão máxima por um minuto. Qual manobra é essa, e o que um resultado negativo significa?", "alternativas": ["Phalen", "Gerber", "Speed", "Tinel", "Cozen"], "gabarito": "A", "justificativa": "Manobra: Phalen. Achado alterado: Parestesia no território mediano. Significado: Compressão do mediano. Negativo não exclui neuropatia. Ver slide 37 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 37, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 40, "nivel": "dificil", "enunciado": "Operário com formigamento no território mediano. Ao percutir o punho, o médico nota a sensação, mas o formigamento não se estende até os dedos. Qual manobra é essa, e por que a dor local à percussão não basta?", "alternativas": ["Tinel", "Speed", "Cozen", "Patte", "Phalen"], "gabarito": "A", "justificativa": "Manobra: Tinel. Achado alterado: Parestesia (formigamento) no território mediano. Significado: Sugere compressão do mediano. Dor local à percussão não é Tinel positivo; nenhum dos dois testes (Tinel e Phalen), isolado, confirma ou exclui. Ver slide 38 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 38, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 41, "nivel": "dificil", "enunciado": "Paciente com dor sobre o estiloide radial ao desviar o punho para o lado ulnar, com o polegar fletido sobre a palma. Qual manobra provoca essa dor, e qual doença ela sugere?", "alternativas": ["Finkelstein (De Quervain)", "Artrocentese diagnóstica", "Palpação do aumento de volume", "Adução cruzada (AC)", "Matriz de diferenciação cinética"], "gabarito": "A", "justificativa": "Manobra: Finkelstein (De Quervain). Achado alterado: Dor sobre o estiloide radial. Significado: Tenossinovite do primeiro compartimento dorsal. Ver slide 39 do professor.", "tecnica": "Aula 7.1 - Semiologia osteomioarticular I", "slide": 39, "pdf": "pdf/aula-07-1.pdf", "tipo": "nome"}, {"id": 42, "nivel": "dificil", "enunciado": "Adolescente com assimetria do dorso visível em pé. Na flexão anterior do tronco, a giba costal persiste. Qual manobra é essa, e o que a persistência da giba indica?", "alternativas": ["Lasègue (elevação do membro estendido)", "Lasègue cruzado", "Teste de Adams (flexão anterior do tronco)", "Ponto-gatilho", "Gaveta posterior (sinal da queda posterior)"], "gabarito": "C", "justificativa": "Manobra: Teste de Adams (flexão anterior do tronco). Achado alterado: Giba costal ou lombar que persiste na flexão. Significado: Escoliose estrutural. Se a giba se corrige na flexão, é escoliose postural. Ver slide 4 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 4, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 43, "nivel": "dificil", "enunciado": "Paciente de 50 anos com lombalgia crônica e rigidez. Ao flexionar a coluna lombar, a distância entre as marcas aumenta menos que o esperado. Qual manobra mede essa flexão, e o que a limitação sugere?", "alternativas": ["Schober", "Bragard", "Lasègue", "Ponto-gatilho", "Lasègue cruzado"], "gabarito": "A", "justificativa": "Manobra: Schober. Achado alterado: Aumento menor que 5 cm (A-B menor que 20 cm). Significado: Limitação da flexão lombar, como na espondilite anquilosante. Não confirma espondilite isoladamente. Ver slide 5 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 5, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 44, "nivel": "dificil", "enunciado": "Paciente com dor irradiada que vai do glúteo à face posterior da perna. Ao elevar o membro estendido, a dor aparece entre cerca de 30 e 70 graus e atinge abaixo do joelho. Qual manobra é essa, e qual raiz ela tensiona?", "alternativas": ["Lasègue (elevação do membro estendido)", "Teste de Adams (flexão anterior do tronco)", "Lasègue cruzado", "Ponto-gatilho", "Bragard"], "gabarito": "A", "justificativa": "Manobra: Lasègue (elevação do membro estendido). Achado alterado: Dor irradiada abaixo do joelho entre cerca de 30 e 70 graus. Significado: Tensão de raízes L4 a S1, sobretudo L5 e S1. Dor só na face posterior da coxa indica isquiotibiais, e não é positivo. Ver slide 7 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 7, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 45, "nivel": "dificil", "enunciado": "Paciente com ciatalgia à direita. Ao elevar a perna esquerda estendida, a dor reproduz a ciatalgia do lado direito. Qual manobra é essa, e qual é sua sensibilidade e especificidade?", "alternativas": ["Lasègue cruzado", "Ponto-gatilho", "Schober", "Bragard", "Gaveta anterior"], "gabarito": "A", "justificativa": "Manobra: Lasègue cruzado. Achado alterado: Reprodução da ciatalgia do lado afetado. Significado: Compressão radicular. Pouco sensível, muito específico. Ver slide 7 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 7, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 46, "nivel": "dificil", "enunciado": "Paciente com dor lombar e distância de flexão lombar reduzida. Qual manobra é essa, e o que a limitação sugere em um contexto de rigidez inflamatória?", "alternativas": ["Lasègue", "Bragard", "Schober", "Ponto-gatilho", "Lasègue cruzado"], "gabarito": "C", "justificativa": "Manobra: Schober. Achado alterado: Aumento menor que 5 cm. Significado: Limitação da flexão lombar, compatível com espondilite anquilosante. Ver slide 8 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 8, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 47, "nivel": "dificil", "enunciado": "Paciente com dor lombar. Ao dorsiflexionar o pé com o joelho estendido, a dor irradiada retorna. Qual manobra é essa, e o que ela diferencia de uma dor muscular?", "alternativas": ["Bragard", "Lasègue", "Schober", "Ponto-gatilho", "Lasègue cruzado"], "gabarito": "A", "justificativa": "Manobra: Bragard. Achado alterado: Retorno da dor irradiada. Significado: Tensão neural radicular, e não dor muscular. Ver slide 8 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 8, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 48, "nivel": "dificil", "enunciado": "Paciente com dor irradiada que aparece entre 30 e 45 graus e de novo entre 70 graus, abaixo do joelho. Qual manobra é essa, e quais raízes são mais comumente tensionadas?", "alternativas": ["Bragard", "Schober", "Lasègue", "Ponto-gatilho", "Lasègue cruzado"], "gabarito": "C", "justificativa": "Manobra: Lasègue. Achado alterado: Dor irradiada além do joelho entre 30 e 45 graus e 70 graus. Significado: Tensão radicular (L5 e S1 mais comuns). Negativo torna hérnia improvável. Ver slide 16 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 16, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 49, "nivel": "dificil", "enunciado": "Paciente com dor lombar e ciatalgia. Ao elevar o membro contralateral estendido, a dor aparece no membro examinado. Qual manobra é essa, e qual é sua sensibilidade para hérnia lombar?", "alternativas": ["Ponto-gatilho", "Lasègue cruzado", "Schober", "Bragard", "Patrick (FABER)"], "gabarito": "B", "justificativa": "Manobra: Lasègue cruzado. Achado alterado: Dor no membro examinado. Significado: Muito específico, pouco sensível para hérnia lombar. Ver slide 16 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 16, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 50, "nivel": "dificil", "enunciado": "Paciente com dor muscular localizada. Ao pressionar um nódulo tenso no trapézio, a dor habitual é reproduzida. Qual é esse ponto e qual síndrome ele caracteriza?", "alternativas": ["Lasègue cruzado", "Lasègue", "Bragard", "Ponto-gatilho", "Schober"], "gabarito": "D", "justificativa": "Manobra: Ponto-gatilho. Achado alterado: Pressão reproduz a dor habitual. Significado: Síndrome dolorosa miofascial, distinta da fibromialgia. Ver slide 22 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 22, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 51, "nivel": "dificil", "enunciado": "Mulher com dor na região inguinal ao cruzar a perna sobre a outra, com rotação externa do quadril. A dor é inguinal. Qual manobra é essa, e qual articulação é sugerida pela dor inguinal?", "alternativas": ["Gaveta anterior", "Estresse em varo", "Estresse em valgo", "Patrick (FABER)", "Trendelenburg"], "gabarito": "D", "justificativa": "Manobra: Patrick (FABER). Achado alterado: Dor inguinal ou dor posterior sacroilíaca reproduzida. Significado: Dor inguinal: coxofemoral. Dor posterior: sacroilíaca. É teste de provocação e não define diagnóstico sozinho. Ver slide 12 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 12, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 52, "nivel": "dificil", "enunciado": "Paciente com dor posterior no quadril. Com o paciente em decúbito dorsal, o examinador hiperestende uma perna enquanto flexiona a outra. Qual manobra provoca a dor, e o que ela não comprova isoladamente?", "alternativas": ["Gaenslen", "Thompson", "McMurray", "Lachman", "Thomas"], "gabarito": "A", "justificativa": "Manobra: Gaenslen. Achado alterado: Reprodução da dor posterior habitual na região sacroilíaca. Significado: Dor sacroilíaca. Não comprova sacroiliíte isoladamente. Ver slide 13 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 13, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 53, "nivel": "dificil", "enunciado": "Idoso com dor no quadril e limitação para girar a coxa para dentro. A limitação é comparada com o lado oposto. Qual manobra é essa, e qual diagnóstico a limitação da rotação interna sugere?", "alternativas": ["Apley (compressão e distração)", "Choque patelar (sinal da tecla)", "Regras de Ottawa (tornozelo e pé)", "Compressão lateral das MCF", "Rotação do quadril em 90 graus"], "gabarito": "E", "justificativa": "Manobra: Rotação do quadril em 90 graus. Achado alterado: Limitação de amplitude, sobretudo da rotação interna, comparada ao lado oposto. Significado: Artrose coxofemoral (rotação interna é a primeira a limitar). Dor inguinal sugere origem intra-articular; dor lateral com trocânter, periarticular. Ver slide 14 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 14, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 54, "nivel": "dificil", "enunciado": "Paciente com suspeita de radiculopatia lombar. O médico pede que o paciente caminhe sobre os calcanhares e depois sobre a ponta dos pés. Qual teste é esse, e qual raiz cada incapacidade sugere?", "alternativas": ["Gaveta posterior (sinal da queda posterior)", "Força contra resistência (tornozelo)", "Regras de Ottawa (tornozelo e pé)", "Choque patelar (sinal da tecla)", "Marcha nos calcanhares e na ponta dos pés"], "gabarito": "E", "justificativa": "Manobra: Marcha nos calcanhares e na ponta dos pés. Achado alterado: Incapacidade sobre os calcanhares (L4-L5) ou sobre a ponta dos pés (S1). Significado: Teste rápido de raiz à beira do leito. Ver slide 15 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 15, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 55, "nivel": "dificil", "enunciado": "Paciente que, ao andar, deixa a pelve cair do lado oposto ao apoio do pé elevado. Ao ficar em um pé só, a pelve cai do lado do pé elevado. Qual teste é esse, e qual músculo está fraco?", "alternativas": ["Sinal da onda", "Gaveta anterior", "Trendelenburg", "Patrick (FABER)", "Estresse em varo"], "gabarito": "C", "justificativa": "Manobra: Trendelenburg. Achado alterado: Queda da pelve do lado do pé elevado. Significado: Fraqueza dos abdutores do quadril (glúteo médio) do lado apoiado. Na marcha gera a marcha de Trendelenburg. Ver slide 15 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 15, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 56, "nivel": "dificil", "enunciado": "Paciente em decúbito dorsal, com a perna contralateral flexionada contra o tórax. A coxa testada se eleva da maca. Qual manobra é essa, e o que o achado sugere sobre o quadril?", "alternativas": ["Lachman", "McMurray", "Gaenslen", "Thomas", "Thompson"], "gabarito": "D", "justificativa": "Manobra: Thomas. Achado alterado: A coxa testada se eleva da maca. Significado: Contratura em flexão do quadril. Com a perna pendente na borda da maca, a extensão do joelho sugere encurtamento do reto femoral. Sem retificar a lordose, a hiperlordose esconde a contratura (falso-negativo). Ver slide 16 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 16, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 57, "nivel": "dificil", "enunciado": "Joelho com derrame. O examinador comprime a bolsa suprapatelar e percebe onda de líquido na face medial que reaparece. Qual manobra é essa, e qual tamanho de derrame ela detecta melhor?", "alternativas": ["Trendelenburg", "Gaveta anterior", "Sinal da onda", "Patrick (FABER)", "Estresse em varo"], "gabarito": "C", "justificativa": "Manobra: Sinal da onda. Achado alterado: Onda de líquido que reaparece na face medial. Significado: Derrame pequeno. Nos derrames volumosos e tensos pode não aparecer. Ver slide 18 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 18, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 58, "nivel": "dificil", "enunciado": "Joelho com derrame moderado. Ao pressionar a patela contra o fêmur com a outra mão, a patela sente um impacto e volta a flutuar. Qual manobra é essa, e em que tipo de derrame ela falha?", "alternativas": ["Apley (compressão e distração)", "Rotação do quadril em 90 graus", "Regras de Ottawa (tornozelo e pé)", "Choque patelar (sinal da tecla)", "Compressão lateral das MCF"], "gabarito": "D", "justificativa": "Manobra: Choque patelar (sinal da tecla). Achado alterado: A patela desce, choca contra o fêmur e retorna. Significado: Derrame moderado a volumoso. Falso-negativo com derrame pequeno ou muito tenso. Ver slide 19 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 19, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 59, "nivel": "dificil", "enunciado": "Atleta com dor e instabilidade no joelho após torção. Com o joelho fletido a 30 graus, o examinador traciona a tíbia para a frente e encontra translação anterior maior que a do lado oposto, com parada mole. Qual teste é esse, e por que ele é considerado o de escolha?", "alternativas": ["Lachman", "Gaenslen", "Thompson", "McMurray", "Thomas"], "gabarito": "A", "justificativa": "Manobra: Lachman. Achado alterado: Translação anterior maior que a do lado oposto, com parada mole. Significado: Lesão do LCA. Teste de escolha. Defesa dos isquiotibiais gera falso-negativo. Ver slide 20 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 20, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 60, "nivel": "dificil", "enunciado": "Paciente com instabilidade do joelho. Com o joelho fletido a 90 graus, a tíbia desliza para a frente, sem ponto final firme. Qual teste é esse, e em que situação ele dá falso-positivo?", "alternativas": ["Patrick (FABER)", "Estresse em varo", "Trendelenburg", "Estresse em valgo", "Gaveta anterior"], "gabarito": "E", "justificativa": "Manobra: Gaveta anterior. Achado alterado: Deslizamento anterior excessivo sem ponto final firme. Significado: Lesão do LCA. Se a tíbia já estava caída para trás, o achado é falso-positivo e sugere LCP. Ver slide 23 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 23, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 61, "nivel": "dificil", "enunciado": "Paciente com joelho instável após queda. Com o joelho fletido a 90 graus, a tíbia cai para trás em relação ao fêmur. Qual manobra é essa, e qual ligamento está lesado?", "alternativas": ["Marcha nos calcanhares e na ponta dos pés", "Força contra resistência (tornozelo)", "Regras de Ottawa (tornozelo e pé)", "Gaveta posterior (sinal da queda posterior)", "Palpação do corpo do pênis e ordenha uretral"], "gabarito": "D", "justificativa": "Manobra: Gaveta posterior (sinal da queda posterior). Achado alterado: Tíbia caída para trás ou deslocamento posterior excessivo sem ponto final. Significado: Lesão do LCP. Ver slide 24 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 24, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 62, "nivel": "dificil", "enunciado": "Paciente com dor na face medial do joelho após torção. Com o joelho em extensão, o examinador aplica abertura medial e sente a abertura. Qual manobra é essa, e por que uma abertura em extensão sugere lesão associada?", "alternativas": ["Estresse em varo", "Patrick (FABER)", "Gaveta anterior", "Observação da marcha", "Estresse em valgo"], "gabarito": "E", "justificativa": "Manobra: Estresse em valgo. Achado alterado: Abertura medial excessiva sem ponto final firme, ou dor na interlinha medial. Significado: Lesão do LCM. Abertura em extensão sugere lesão associada. Ver slide 25 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 25, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 63, "nivel": "dificil", "enunciado": "Paciente com dor e abertura lateral do joelho. O examinador aplica abertura lateral com o joelho em extensão e sente deslocamento excessivo sem ponto final. Qual manobra é essa, e qual ligamento é testado?", "alternativas": ["Estresse em varo", "Estresse em valgo", "Patrick (FABER)", "Gaveta anterior", "Trendelenburg"], "gabarito": "A", "justificativa": "Manobra: Estresse em varo. Achado alterado: Abertura lateral excessiva sem ponto final firme. Significado: Lesão do LCL (menos comum que a do LCM). Ver slide 26 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 26, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 64, "nivel": "dificil", "enunciado": "Paciente com dor e estalido no joelho. Ao fletir e estender a perna sob rotação, com o joelho pressionado, o examinador percebe estalido palpável com dor. Qual manobra é essa, e o que o estalido indica?", "alternativas": ["Thompson", "Gaenslen", "Lachman", "McMurray", "Thomas"], "gabarito": "D", "justificativa": "Manobra: McMurray. Achado alterado: Estalido palpável com dor durante a extensão. Significado: Lesão meniscal no compartimento testado. Estalido indolor isolado é inespecífico. Ver slide 27 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 27, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 65, "nivel": "dificil", "enunciado": "Paciente com dor no joelho. O examinador faz rotação com o joelho fletido e, ao comprimir a articulação, percebe dor ou estalido. Em outra etapa, distrai a articulação e a dor desaparece. Qual manobra é essa, e o que cada etapa avalia?", "alternativas": ["Rotação do quadril em 90 graus", "Choque patelar (sinal da tecla)", "Regras de Ottawa (tornozelo e pé)", "Compressão lateral das MCF", "Apley (compressão e distração)"], "gabarito": "E", "justificativa": "Manobra: Apley (compressão e distração). Achado alterado: Dor ou estalido na compressão; dor na distração. Significado: Compressão: meniscos (rotação externa, medial; rotação interna, lateral). Distração: colaterais (rotação externa, LCM; rotação interna, LCL). Ver slide 28 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 28, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 66, "nivel": "dificil", "enunciado": "Paciente com dor aguda no tornozelo que impede o esforço ao flexionar contra resistência, mas o passivo é normal. Qual manobra é essa, e o que a dor aguda simula?", "alternativas": ["Força contra resistência (tornozelo)", "Regras de Ottawa (tornozelo e pé)", "Choque patelar (sinal da tecla)", "Marcha nos calcanhares e na ponta dos pés", "Rotação do quadril em 90 graus"], "gabarito": "A", "justificativa": "Manobra: Força contra resistência (tornozelo). Achado alterado: Dor com força preservada no passivo, ou fraqueza indolor. Significado: Dor aguda inibe o esforço e simula paresia. Fraqueza indolor sugere causa neurológica. Ver slide 31 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 31, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 67, "nivel": "dificil", "enunciado": "Homem que sofreu queda com dor no calcanhar e não consegue ficar na ponta do pé. Ao comprimir a panturrilha, o pé não se move em flexão plantar. Qual teste é esse, e o que a flexão plantar ativa preservada não afasta?", "alternativas": ["McMurray", "Gaenslen", "Thompson", "Lachman", "Thomas"], "gabarito": "C", "justificativa": "Manobra: Thompson. Achado alterado: Ausência de flexão plantar à compressão. Significado: Ruptura do tendão do calcâneo. Flexão plantar ativa preservada não afasta ruptura. Sinônimos: Simmonds e Thompson-Doherty. Ver slide 32 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 32, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 68, "nivel": "dificil", "enunciado": "Paciente com artrite reumatoide em início. O examinador comprime as articulações metacarpofalangeanas e percebe dor localizada. Qual manobra é essa, e ela é diagnóstica?", "alternativas": ["Apley (compressão e distração)", "Rotação do quadril em 90 graus", "Compressão lateral das MCF", "Choque patelar (sinal da tecla)", "Observação da marcha"], "gabarito": "C", "justificativa": "Manobra: Compressão lateral das MCF. Achado alterado: Dor localizada nas MCF. Significado: Triagem de sinovite (ex.: AR). Não é diagnóstico. Ver slide 38 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 38, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 69, "nivel": "dificil", "enunciado": "Idoso com marcha curta, passos pequenos e braços pouco balançando. Qual padrão de marcha é descrito e qual é o diagnóstico sindrômico sugerido?", "alternativas": ["Estresse em valgo", "Estresse em varo", "Observação da marcha", "Gaveta anterior", "Palpação de elevação"], "gabarito": "C", "justificativa": "Manobra: Observação da marcha. Achado alterado: Encurtamento do apoio de um lado, queda da pelve, passos curtos, pé caído, oscilação bilateral. Significado: Antálgica (encurta o apoio doloroso); Trendelenburg (pelve); parkinsoniana (passos curtos); escarvante (pé caído, L5 ou fibular); anserina (miopatia, fraqueza bilateral). Ver slide 39 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 39, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 70, "nivel": "dificil", "enunciado": "Homem que torceu o tornozelo e não consegue dar quatro passos sem apoio. Ao palpar a base do quinto metatarso, sente dor. Qual critério orienta a radiografia, e o que ele indica?", "alternativas": ["Choque patelar (sinal da tecla)", "Força contra resistência (tornozelo)", "Regras de Ottawa (tornozelo e pé)", "Rotação do quadril em 90 graus", "Apley (compressão e distração)"], "gabarito": "C", "justificativa": "Manobra: Regras de Ottawa (tornozelo e pé). Achado alterado: Dor à palpação em qualquer desses pontos, ou incapacidade de dar 4 passos. Significado: Indica radiografia após trauma de tornozelo ou pé. Ver slide 41 do professor.", "tecnica": "Aula 8 - Semiologia do Sistema Osteomioarticular II", "slide": 41, "pdf": "pdf/aula-08.pdf", "tipo": "nome"}, {"id": 71, "nivel": "dificil", "enunciado": "Paciente com paraparesia espástica. Ao estimular a planta do pé com um objeto, o hálux se estende. Qual reflexo é esse, e que lesão ele sugere?", "alternativas": ["Babinski (reflexo cutâneo-plantar)", "Reflexos patelar e aquileu", "Sensibilidade por dermátomo e anestesia em sela", "Reflexos bicipital, braquiorradial e tricipital", "Lhermitte"], "gabarito": "A", "justificativa": "Manobra: Babinski (reflexo cutâneo-plantar). Achado alterado: Extensão do hálux. Significado: Sinal de neurônio motor superior: mielopatia cervical. Ver slide 11 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 11, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 72, "nivel": "dificil", "enunciado": "Paciente com tetraparesia espástica. Ao estender e flexionar rapidamente o dedo médio, o polegar e o indicador se flexionam reflexamente. Qual sinal é esse, e qual nível da lesão ele sugere?", "alternativas": ["Lhermitte", "Hoffmann", "Reflexos patelar e aquileu", "Babinski (reflexo cutâneo-plantar)", "Sensibilidade por dermátomo e anestesia em sela"], "gabarito": "B", "justificativa": "Manobra: Hoffmann. Achado alterado: Flexão reflexa do polegar e do indicador. Significado: Sinal de neurônio motor superior cervical. Ver slide 11 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 11, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 73, "nivel": "dificil", "enunciado": "Paciente com esclerose múltipla relata choque elétrico que desce pela coluna ao fletir o pescoço. Qual sinal é esse, e qual é sua localização?", "alternativas": ["Lhermitte", "Hoffmann", "Reflexos patelar e aquileu", "Babinski (reflexo cutâneo-plantar)", "Sensibilidade por dermátomo e anestesia em sela"], "gabarito": "A", "justificativa": "Manobra: Lhermitte. Achado alterado: Choque elétrico descendente pela coluna ou membros. Significado: Sugere compressão medular cervical. Ver slide 11 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 11, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 74, "nivel": "dificil", "enunciado": "Paciente com dor lombar e fraqueza ao caminhar na ponta dos pés. O examinador testa cada grupo muscular separadamente, em um lado e no outro. Qual é essa avaliação, e o que ela localiza junto com o reflexo?", "alternativas": ["Reflexos bicipital, braquiorradial e tricipital", "Força por miótomo (dorsiflexão, inversão, flexão plantar, extensão do hálux)", "Sensibilidade por dermátomo e anestesia em sela", "Babinski (reflexo cutâneo-plantar)", "Reflexos patelar e aquileu"], "gabarito": "B", "justificativa": "Manobra: Força por miótomo (dorsiflexão, inversão, flexão plantar, extensão do hálux). Achado alterado: Fraqueza em um miótomo específico. Significado: Localiza a raiz acometida junto com o reflexo. Ver slide 15 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 15, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 75, "nivel": "dificil", "enunciado": "Paciente com dor ciática e reflexo aquileu ausente. Qual reflexo é avaliado, e o que a sua ausência, junto a déficit de força, confirma?", "alternativas": ["Babinski (reflexo cutâneo-plantar)", "Lhermitte", "Reflexos patelar e aquileu", "Hoffmann", "Reflexos bicipital, braquiorradial e tricipital"], "gabarito": "C", "justificativa": "Manobra: Reflexos patelar e aquileu. Achado alterado: Reflexo diminuído ou abolido. Significado: Confirma a raiz com déficit de força e dor. Ver slide 15 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 15, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 76, "nivel": "dificil", "enunciado": "Paciente com dor e parestesia no membro superior. O reflexo do tríceps está diminuído. Qual é o grupo de reflexos avaliado e o que ele localiza?", "alternativas": ["Sensibilidade por dermátomo e anestesia em sela", "Babinski (reflexo cutâneo-plantar)", "Reflexos bicipital, braquiorradial e tricipital", "Reflexos patelar e aquileu", "Força por miótomo (dorsiflexão, inversão, flexão plantar, extensão do hálux)"], "gabarito": "C", "justificativa": "Manobra: Reflexos bicipital, braquiorradial e tricipital. Achado alterado: Reflexo diminuído. Significado: Localização de raiz cervical. Ver slide 17 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 17, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 77, "nivel": "dificil", "enunciado": "Paciente com retenção urinária, dor lombar e anestesia na região perineal e nas nádegas. Qual avaliação é essa, e qual anestesia é sinal de síndrome de cauda equina?", "alternativas": ["Reflexos bicipital, braquiorradial e tricipital", "Babinski (reflexo cutâneo-plantar)", "Sensibilidade por dermátomo e anestesia em sela", "Reflexos patelar e aquileu", "Força por miótomo (dorsiflexão, inversão, flexão plantar, extensão do hálux)"], "gabarito": "C", "justificativa": "Manobra: Sensibilidade por dermátomo e anestesia em sela. Achado alterado: Hipoestesia no dermátomo; anestesia em sela. Significado: Sensibilidade por raiz; anestesia em sela é sinal de cauda equina. Ver slide 18 do professor.", "tecnica": "Aula 8.1 - Síndromes axiais, radiculares e dor musculoesquelética", "slide": 18, "pdf": "pdf/aula-08-1.pdf", "tipo": "nome"}, {"id": 78, "nivel": "dificil", "enunciado": "Mulher com tumefação dolorosa e quente no pequeno lábio, de início súbito. O exame revela secreção purulenta. Qual palpação é essa, e como diferenciar um cisto indolor de um abscesso?", "alternativas": ["Palpação de Bartholin e ordenha de Skene", "Avaliação da força do assoalho pélvico", "Testes do corrimento à beira do leito", "Manobra de Hegar com pinça de Pozzi", "Coleta cervical com espátula de Ayres e escova"], "gabarito": "A", "justificativa": "Manobra: Palpação de Bartholin e ordenha de Skene. Achado alterado: Tumefação dolorosa, calor, rubor ou secreção purulenta. Significado: Cisto de Bartholin (indolor) versus abscesso (dor intensa, calor e rubor); infecção de Skene. Ver slide 34 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 34, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 79, "nivel": "dificil", "enunciado": "Mulher multípara com sensação de peso vaginal. Ao esforço com a bexiga cheia, a parede anterior protrai pelo introito e há perda urinária. Qual manobra é essa, e qual compartimento está protraído?", "alternativas": ["Teste de Schiller e ácido acético", "Manobra de Hegar com pinça de Pozzi", "Testes do corrimento à beira do leito", "Inspeção dinâmica com Valsalva", "Introdução do espéculo"], "gabarito": "D", "justificativa": "Manobra: Inspeção dinâmica com Valsalva. Achado alterado: Protrusão da parede anterior, posterior ou descida do colo, com perda urinária. Significado: Cistocele ou cistouretrocele (anterior), retocele (posterior), prolapso uterino (ápice) e incontinência de esforço. Ver slide 37 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 37, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 80, "nivel": "dificil", "enunciado": "Mulher que, na coleta, sente dor e o colo não fica exposto. A amostra colhida parece inviável. Qual erro de técnica deve ser evitado ao introduzir o instrumento, e qual é a sua consequência?", "alternativas": ["Toque retovaginal", "Manobra de Weibel", "Toque bimanual", "Inspeção dinâmica com Valsalva", "Introdução do espéculo"], "gabarito": "E", "justificativa": "Manobra: Introdução do espéculo. Achado alterado: Dor, colo não exposto ou amostra inviável. Significado: Erros comuns: gel antes da coleta ou abrir as lâminas antes de alcançar o fundo. Ver slide 42 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 42, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 81, "nivel": "dificil", "enunciado": "Mulher com colo corado após aplicação de solução. Em algumas áreas, a solução não cora o epitélio. Qual teste é esse, e qual conduta a presença de áreas iodo-negativas exige?", "alternativas": ["Teste de Schiller e ácido acético", "Manobra de Hegar com pinça de Pozzi", "Inspeção dinâmica com Valsalva", "Testes do corrimento à beira do leito", "Avaliação da força do assoalho pélvico"], "gabarito": "A", "justificativa": "Manobra: Teste de Schiller e ácido acético. Achado alterado: Áreas iodo-negativas, acetobrancas ou azuladas. Significado: Risco de atipia celular: exige biópsia dirigida. Ver slide 49 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 49, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 82, "nivel": "dificil", "enunciado": "Mulher com corrimento com odor de peixe, pH da secreção acima de 4,5 e células epiteliais com bordas indistintas. Qual avaliação à beira do leito identifica esse quadro sem esperar cultura?", "alternativas": ["Avaliação da força do assoalho pélvico", "Manobra de Hegar com pinça de Pozzi", "Palpação de Bartholin e ordenha de Skene", "Teste de Schiller e ácido acético", "Testes do corrimento à beira do leito"], "gabarito": "E", "justificativa": "Manobra: Testes do corrimento à beira do leito. Achado alterado: pH maior que 4,5, odor de peixe, clue cells, flagelados ou hifas. Significado: Vaginose bacteriana, tricomoníase ou candidíase, sem esperar cultura. Ver slide 56 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 56, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 83, "nivel": "dificil", "enunciado": "Mulher de 40 anos com resultado do teste de HPV. A genotipagem mostra os tipos 16 ou 18. Qual é a conduta a seguir, segundo a genotipagem?", "alternativas": ["Palpação de Bartholin e ordenha de Skene", "Avaliação da força do assoalho pélvico", "Testes do corrimento à beira do leito", "Coleta cervical com espátula de Ayres e escova", "Palpação com a técnica de Velpeau ou Bloodgood"], "gabarito": "D", "justificativa": "Manobra: Coleta cervical com espátula de Ayres e escova. Achado alterado: Resultado do DNA-HPV (16 ou 18, outros tipos, não detectado). Significado: Conduta conforme genotipagem: colposcopia, citologia reflexa ou repetir em 5 anos. Ver slide 57 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 57, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 84, "nivel": "dificil", "enunciado": "Mulher com dor pélvica aguda, com dor à mobilização do colo e massa anexial palpável. Qual exame ginecológico é esse, e o que a dor à mobilização do colo sugere?", "alternativas": ["Manobra de Weibel", "Toque retovaginal", "Introdução do espéculo", "Toque bimanual", "Inspeção dinâmica com Valsalva"], "gabarito": "D", "justificativa": "Manobra: Toque bimanual. Achado alterado: Dor à mobilização do colo, nodularidade nos fórnices, massa anexial. Significado: DIP, gravidez ectópica ou apendicite (dor); endometriose (nodularidade); registrar o útero com parâmetros. Ver slide 59 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 59, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 85, "nivel": "dificil", "enunciado": "Mulher com dor na defecação e nodularidade no fundo de saco posterior. O toque vaginal não alcança a região. Qual toque é indicado, e quais estruturas ele examina que o vaginal não alcança?", "alternativas": ["Manobra de Weibel", "Toque bimanual", "Introdução do espéculo", "Inspeção dinâmica com Valsalva", "Toque retovaginal"], "gabarito": "E", "justificativa": "Manobra: Toque retovaginal. Achado alterado: Nodularidade do septo, massa no fundo de saco de Douglas, útero retrovertido fixo. Significado: Alcança o que o toque vaginal não alcança (ligamentos uterossacros, septo e fundo de saco). Ver slide 64 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 64, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 86, "nivel": "dificil", "enunciado": "Mulher com massa pélvica. Ao mover o colo, o examinador percebe que a massa se move junto com o colo, e não de forma independente. Qual manobra é essa, e de qual origem é a massa?", "alternativas": ["Toque retovaginal", "Manobra de Weibel", "Toque bimanual", "Introdução do espéculo", "Inspeção dinâmica com Valsalva"], "gabarito": "B", "justificativa": "Manobra: Manobra de Weibel. Achado alterado: O colo acompanha o movimento ou permanece estacionário. Significado: Colo acompanha: massa uterina (mioma); estacionário: massa anexial (cisto). Ver slide 67 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 67, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 87, "nivel": "dificil", "enunciado": "Mulher com massa pélvica. O examinador usa um instrumento na cérvix e percebe que o cabo se move junto com a massa. Qual manobra é essa, e que cuidado técnico ela exige?", "alternativas": ["Testes do corrimento à beira do leito", "Manobra de Hegar com pinça de Pozzi", "Teste de Schiller e ácido acético", "Avaliação da força do assoalho pélvico", "Inspeção dinâmica com Valsalva"], "gabarito": "B", "justificativa": "Manobra: Manobra de Hegar com pinça de Pozzi. Achado alterado: O cabo da pinça se move junto com a massa. Significado: Massa de origem uterina; manobra instrumental que exige técnica rigorosa e consentimento. Ver slide 68 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 68, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 88, "nivel": "dificil", "enunciado": "Mulher com dor pélvica crônica e pontos-gatilho no assoalho pélvico. Ao comprimir o canal anal com dedos, a compressão é fraca e o paciente contrai os glúteos. Qual avaliação é essa, e o que ela identifica?", "alternativas": ["Testes do corrimento à beira do leito", "Palpação de Bartholin e ordenha de Skene", "Manobra de Hegar com pinça de Pozzi", "Avaliação da força do assoalho pélvico", "Teste de Schiller e ácido acético"], "gabarito": "D", "justificativa": "Manobra: Avaliação da força do assoalho pélvico. Achado alterado: Compressão fraca, recrutamento de abdome, adutores ou glúteos, pontos-gatilho dolorosos, perda de urina. Significado: Espasmo, fraqueza ou disfunção do assoalho pélvico. Ver slide 69 do professor.", "tecnica": "Aula 9.1 - Semiologia do sistema genitourinário feminino", "slide": 69, "pdf": "pdf/aula-09-1.pdf", "tipo": "nome"}, {"id": 89, "nivel": "dificil", "enunciado": "Homem com secreção uretral que não é visível em repouso. Qual manobra é essa, e qual exame confirma a etiologia da secreção?", "alternativas": ["Sinal de Prehn", "Ordenha uretral", "Sinal de Brunzel", "Escore TWIST", "Manobra de Chevassu"], "gabarito": "B", "justificativa": "Manobra: Ordenha uretral. Achado alterado: Secreção uretral. Significado: Fundamental se há queixa de secreção não visível em repouso; Gram e cultura confirmam a etiologia. Ver slide 32 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 32, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 90, "nivel": "dificil", "enunciado": "Homem com jato urinário fino e dificuldade para expor a glande. Ao comprimir suavemente a glande, o examinador observa o meato. Qual manobra é essa, e que diagnósticos ela sugere?", "alternativas": ["Transiluminação do escroto", "Varicocele em pé com Valsalva", "Distorção manual do testículo", "Compressão suave da glande", "Palpar acima da massa escrotal"], "gabarito": "D", "justificativa": "Manobra: Compressão suave da glande. Achado alterado: Estenose, secreção, posição anômala do meato. Significado: Estenose de meato, hipospádia, uretrite. Ver slide 33 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 33, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 91, "nivel": "dificil", "enunciado": "Homem com nódulo duro e indolor no testículo, sem dor. Qual exame de palpação unimanual é esse, e o que um nódulo duro representa até prova em contrário?", "alternativas": ["Palpação do testículo e do epidídimo (unimanual)", "Pesquisa de hérnia inguinal (em pé, com tosse)", "Palpação do corpo do pênis e ordenha uretral", "Toque retal: técnica passo a passo", "Avaliação de via aérea, respiração e circulação (ABC)"], "gabarito": "A", "justificativa": "Manobra: Palpação do testículo e do epidídimo (unimanual). Achado alterado: Nódulo duro e indolor; epidídimo doloroso. Significado: Nódulo duro é câncer até prova em contrário; epididimite pela dor. Ver slide 37 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 37, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 92, "nivel": "dificil", "enunciado": "Homem com aumento escrotal indolor e transiluminação positiva. Ao tentar palpar acima da massa, os dedos conseguem alcançar o canal inguinal. Qual sinal é esse, e qual diagnóstico se considera?", "alternativas": ["Varicocele em pé com Valsalva", "Distorção manual do testículo", "Retração e devolução do prepúcio", "Palpar acima da massa escrotal", "Toque retal (técnica estruturada)"], "gabarito": "D", "justificativa": "Manobra: Palpar acima da massa escrotal. Achado alterado: Dedos conseguem palpar acima. Significado: Hidrocele; hérnia escrotal não permite. Ver slide 44 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 44, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 93, "nivel": "dificil", "enunciado": "Homem de 65 anos com queixa urinária. O toque retal revela próstata com nódulo duro. Qual exame é esse, e qual é o alcance do toque normal na triagem?", "alternativas": ["Toque retal (técnica estruturada)", "Retração e devolução do prepúcio", "Palpar acima da massa escrotal", "Toque retal: técnica passo a passo", "Babinski (reflexo cutâneo-plantar)"], "gabarito": "D", "justificativa": "Manobra: Toque retal: técnica passo a passo. Achado alterado: Tônus alterado, massa na ampola, nódulo, assimetria ou dor. Significado: Triagem prostática; o toque normal não exclui câncer; nódulo duro exige investigação urológica. Ver slide 57 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 57, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 94, "nivel": "dificil", "enunciado": "Homem com dor e queixa urinária. Ao toque retal, o examinador encontra tônus alterado e assimetria prostática. Qual é a técnica estruturada aplicada e o que o nódulo duro exige?", "alternativas": ["Toque retal: técnica passo a passo", "Toque retal (técnica estruturada)", "Retração e devolução do prepúcio", "Palpar acima da massa escrotal", "Distorção manual do testículo"], "gabarito": "B", "justificativa": "Manobra: Toque retal (técnica estruturada). Achado alterado: Tônus alterado, massa na ampola, nódulo ou assimetria prostática. Significado: Triagem prostática; nódulo duro exige investigação urológica. Ver slide 58 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 58, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 95, "nivel": "dificil", "enunciado": "Adolescente com dor testicular súbita. Ao tocar a face interna da coxa, o reflexo de elevação do testículo está ausente. Qual reflexo é esse, e o que sua ausência sugere?", "alternativas": ["Manobra de Chevassu", "Sinal do ponto azul", "Reflexo cremastérico", "Sinal de Brunzel", "Observação da marcha"], "gabarito": "C", "justificativa": "Manobra: Reflexo cremastérico. Achado alterado: Ausência de elevação ipsilateral. Significado: Na torção, quase sempre ausente (raízes L1 a L2); reflexo presente sugere, mas não exclui torção. Ver slide 67 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 67, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 96, "nivel": "dificil", "enunciado": "Adolescente com dor testicular. Ao elevar o testículo, a dor não alivia. Qual sinal é esse, e o que ele sugere quanto à origem da dor?", "alternativas": ["Sinal de Prehn", "Ordenha uretral", "Sinal de Brunzel", "Escore TWIST", "Manobra de Chevassu"], "gabarito": "A", "justificativa": "Manobra: Sinal de Prehn. Achado alterado: Dor não alivia. Significado: Pensar em torção (baixa confiabilidade). Ver slide 68 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 68, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 97, "nivel": "dificil", "enunciado": "Adolescente com dor testicular. O testículo afetado está mais alto e em posição horizontal. Qual sinal é esse, e por que o examinador deve comparar com o lado sadio?", "alternativas": ["Ordenha uretral", "Sinal de Prehn", "Manobra de Chevassu", "Sinal de Brunzel", "Sinal do ponto azul"], "gabarito": "D", "justificativa": "Manobra: Sinal de Brunzel. Achado alterado: Testículo afetado mais elevado, com eixo horizontal. Significado: Sugere torção testicular; examine o lado sadio, pois a deformidade em badalo de sino é bilateral em até 80%. Ver slide 69 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 69, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 98, "nivel": "dificil", "enunciado": "Menino com dor escrotal e ponto azulado visível por transparência no polo superior do testículo. Qual sinal é esse, e como conduzir a dúvida diagnóstica?", "alternativas": ["Manobra de Chevassu", "Sinal do ponto azul", "Reflexo cremastérico", "Sinal de Brunzel", "Ordenha uretral"], "gabarito": "B", "justificativa": "Manobra: Sinal do ponto azul. Achado alterado: Ponto azulado ou necrótico visível por transparência. Significado: Torção da hidátide de Morgagni; na dúvida, conduzir como torção testicular. Ver slide 70 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 70, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 99, "nivel": "dificil", "enunciado": "Homem com aumento escrotal. Ao aplicar luz atrás do escroto, a massa deixa passar luz. Qual exame é esse, e o que a transiluminação positiva sugere?", "alternativas": ["Compressão suave da glande", "Distorção manual do testículo", "Varicocele em pé com Valsalva", "Transiluminação do escroto", "Palpar acima da massa escrotal"], "gabarito": "D", "justificativa": "Manobra: Transiluminação do escroto. Achado alterado: Brilho vermelho (transilumina) ou sombra opaca (não transilumina). Significado: Transilumina: massa cística (hidrocele, cisto de epidídimo). Não transilumina: massa sólida (tumor, orquiepididimite, torção, hematocele, maioria das hérnias). Hidrocele irredutível no anel pode ser indistinguível de hérnia estrangulada. Ver slide 71 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 71, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 100, "nivel": "dificil", "enunciado": "Homem com epidídimo aumentado. Ao palpar, o aumento é regular e difuso em um caso, e irregular e multinodular em outro. Qual manobra compara essas consistências, e o que cada padrão sugere?", "alternativas": ["Sinal do ponto azul", "Manobra de Chevassu", "Reflexo cremastérico", "Sinal de Brunzel", "Ordenha uretral"], "gabarito": "B", "justificativa": "Manobra: Manobra de Chevassu. Achado alterado: Aumento regular e difuso; irregular e multinodular; localizado. Significado: Regular e difuso: epididimite aguda. Irregular ou multinodular: tuberculose genitourinária. Localizado: cistos (cabeça ou corpo) ou lesões inespecíficas (cauda). Ver slide 72 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 72, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 101, "nivel": "dificil", "enunciado": "Adolescente com torção testicular em curso. Antes de ir para o centro cirúrgico, o médico tenta reverter a posição do testículo com movimento manual. A dor diminui e o fluxo volta ao Doppler. Qual manobra é essa, e o que ela representa?", "alternativas": ["Varicocele em pé com Valsalva", "Palpar acima da massa escrotal", "Transiluminação do escroto", "Distorção manual do testículo", "Retração e devolução do prepúcio"], "gabarito": "D", "justificativa": "Manobra: Distorção manual do testículo. Achado alterado: Alívio da dor e retorno do fluxo ao Doppler. Significado: Medida temporária de emergência na torção. Ver slide 73 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 73, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 102, "nivel": "dificil", "enunciado": "Adolescente com dor escrotal aguda. Ao aplicar o escore clínico, a soma de pontos é de 6. Qual escore é esse, e qual conduta ele orienta?", "alternativas": ["Sinal de Prehn", "Ordenha uretral", "Sinal de Brunzel", "Manobra de Chevassu", "Escore TWIST"], "gabarito": "E", "justificativa": "Manobra: Escore TWIST. Achado alterado: 5 a 7 pontos, alto risco; 3 a 4, intermediário; 0 a 2, baixo. Significado: Alto risco: cirurgia imediata, sem atrasar pelo Doppler; intermediário: Doppler imediato; baixo: diagnósticos alternativos. Ver slide 74 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 74, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 103, "nivel": "dificil", "enunciado": "Homem que não consegue recolocar o prepúcio sobre a glande após retração, com edema e dor. Qual manobra é essa, e qual urgência ela representa?", "alternativas": ["Toque retal (técnica estruturada)", "Palpar acima da massa escrotal", "Toque retal: técnica passo a passo", "Retração e devolução do prepúcio", "Varicocele em pé com Valsalva"], "gabarito": "D", "justificativa": "Manobra: Retração e devolução do prepúcio. Achado alterado: Prepúcio que não retorna e edema da glande. Significado: Parafimose, urgência. Ver slide 80 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 80, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 104, "nivel": "dificil", "enunciado": "Homem com placa dorsal palpável e encurvamento do pênis durante a ereção. Ao palpar o corpo do pênis, o examinador percebe também induração ventral. Qual manobra é essa, e que diagnósticos ela considera?", "alternativas": ["Palpação do corpo do pênis e ordenha uretral", "Pesquisa de hérnia inguinal (em pé, com tosse)", "Palpação do testículo e do epidídimo (unimanual)", "Toque retal: técnica passo a passo", "Toque retal (técnica estruturada)"], "gabarito": "A", "justificativa": "Manobra: Palpação do corpo do pênis e ordenha uretral. Achado alterado: Placa dorsal, induração ventral, secreção. Significado: Peyronie; estenose ou carcinoma; uretrite. Ver slide 80 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 80, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 105, "nivel": "dificil", "enunciado": "Homem com protrusão na região inguinal que surge em pé, com tosse. O impulso bate no dedo introduzido pelo canal. Qual manobra é essa, e como diferenciar hérnia indireta de direta?", "alternativas": ["Palpação do corpo do pênis e ordenha uretral", "Palpação do testículo e do epidídimo (unimanual)", "Pesquisa de hérnia inguinal (em pé, com tosse)", "Toque retal: técnica passo a passo", "Toque retal (técnica estruturada)"], "gabarito": "C", "justificativa": "Manobra: Pesquisa de hérnia inguinal (em pé, com tosse). Achado alterado: Impulso contra o dedo. Significado: Hérnia inguinal indireta, direta; femoral pela palpação medial à artéria femoral. Ver slide 81 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 81, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}, {"id": 106, "nivel": "dificil", "enunciado": "Adolescente com aumento da bolsa escrotal em pé. Ao realizar manobra de esforço, o aumento não colapsa ao deitar. Qual manobra é essa, e qual achado sugere investigação adicional?", "alternativas": ["Distorção manual do testículo", "Palpar acima da massa escrotal", "Varicocele em pé com Valsalva", "Transiluminação do escroto", "Compressão suave da glande"], "gabarito": "C", "justificativa": "Manobra: Varicocele em pé com Valsalva. Achado alterado: Saco de vermes que não colapsa. Significado: Varicocele; investigar se não colapsa ou surge após os 40 anos. Ver slide 81 do professor.", "tecnica": "Aula 9 - Semiologia do sistema genitourinário masculino", "slide": 81, "pdf": "pdf/aula-09.pdf", "tipo": "nome"}]};
